// leases-placement-sandbox-files.js
const leasesPlacementSandboxFiles={"visibility_receipts.py": "\"\"\"SQLite queue reference with a controlled logical clock; not an SQS implementation.\"\"\"\nimport hashlib\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport tempfile\n\n\nclass Queue:\n    def __init__(self, path):\n        self.db = sqlite3.connect(path)\n        self.db.execute(\"CREATE TABLE messages(id TEXT PRIMARY KEY,event_id TEXT,total INT,visible_at INT,epoch INT,deleted INT)\")\n\n    def put(self, message_id, event_id, total):\n        self.db.execute(\"INSERT INTO messages VALUES(?,?,?,0,0,0)\", (message_id, event_id, total))\n        self.db.commit()\n\n    def receive(self, message_id, now, visibility=30):\n        if visibility <= 0:\n            raise ValueError(\"positive visibility required\")\n        with self.db:\n            self.db.execute(\"BEGIN IMMEDIATE\")\n            row = self.db.execute(\"SELECT event_id,total,visible_at,epoch,deleted FROM messages WHERE id=?\", (message_id,)).fetchone()\n            if row is None or row[4] or row[2] > now:\n                return None\n            epoch = row[3] + 1\n            self.db.execute(\"UPDATE messages SET epoch=?,visible_at=? WHERE id=?\", (epoch, now+visibility, message_id))\n        return {\"message_id\": message_id, \"event_id\": row[0], \"total\": row[1], \"epoch\": epoch,\n                \"receipt_handle\": message_id+\":\"+str(epoch), \"visible_at\": now+visibility}\n\n    def acknowledge(self, receipt, now):\n        # This deliberately strict reference rejects expired/stale handles.\n        # Real SQS documents that an old handle can return success without deleting.\n        with self.db:\n            changed = self.db.execute(\"UPDATE messages SET deleted=1 WHERE id=? AND epoch=? AND visible_at>? AND deleted=0\",\n                                      (receipt[\"message_id\"], receipt[\"epoch\"], now)).rowcount\n        return changed == 1\n\n    def extend(self, receipt, now, visibility):\n        if visibility <= 0:\n            raise ValueError(\"positive visibility required\")\n        with self.db:\n            changed = self.db.execute(\"UPDATE messages SET visible_at=? WHERE id=? AND epoch=? AND visible_at>? AND deleted=0\",\n                                      (now+visibility, receipt[\"message_id\"], receipt[\"epoch\"], now)).rowcount\n        return changed == 1\n\n\ndef apply(db, event_id, total):\n    intent = hashlib.sha256(json.dumps({\"tenant\": \"demo\", \"total\": total}, sort_keys=True).encode()).hexdigest()\n    with db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        row = db.execute(\"SELECT intent,result FROM inbox WHERE tenant='demo' AND event_id=?\", (event_id,)).fetchone()\n        if row:\n            if row[0] != intent:\n                raise ValueError(\"same_business_id_different_intent\")\n            return {\"duplicate\": True, \"total\": row[1]}\n        db.execute(\"INSERT INTO effects VALUES('demo',?,?)\", (event_id, total))\n        db.execute(\"INSERT INTO inbox VALUES('demo',?,?,?)\", (event_id, intent, total))\n    return {\"duplicate\": False, \"total\": total}\n\n\ndef main():\n    with tempfile.TemporaryDirectory(prefix=\"infra-visibility-\") as temporary:\n        root = Path(temporary)\n        queue = Queue(root / \"queue.db\")\n        business = sqlite3.connect(root / \"business.db\")\n        business.executescript(\"CREATE TABLE effects(tenant TEXT,event_id TEXT,total INT,PRIMARY KEY(tenant,event_id));\"\n                               \"CREATE TABLE inbox(tenant TEXT,event_id TEXT,intent TEXT,result INT,PRIMARY KEY(tenant,event_id));\")\n        queue.put(\"msg-A\", \"report-27\", 37)\n        first = queue.receive(\"msg-A\", 0)\n        assert queue.receive(\"msg-A\", 29) is None\n        second = queue.receive(\"msg-A\", 31)\n        assert first[\"receipt_handle\"] != second[\"receipt_handle\"]\n        # The first executor is slow, not stopped: it can still reach the effect service.\n        old_worker = apply(business, first[\"event_id\"], first[\"total\"])\n        stale_ack = queue.acknowledge(first, 32)\n        new_worker = apply(business, second[\"event_id\"], second[\"total\"])\n        current_ack = queue.acknowledge(second, 33)\n        timeline = [{\"at\": 0, \"event\": \"receive_first\"}, {\"at\": 31, \"event\": \"receive_second\"},\n                    {\"at\": 32, \"event\": \"old_executor_applies_and_stale_ack_is_rejected\"},\n                    {\"at\": 33, \"event\": \"new_executor_reuses_and_acknowledges\"}]\n        assert not stale_ack and current_ack\n        assert old_worker == {\"duplicate\": False, \"total\": 37}\n        assert new_worker == {\"duplicate\": True, \"total\": 37}\n        assert queue.receive(\"msg-A\", 100) is None\n\n        queue.put(\"msg-A-republished\", \"report-27\", 37)\n        third = queue.receive(\"msg-A-republished\", 100)\n        replay = apply(business, third[\"event_id\"], third[\"total\"])\n        assert replay[\"duplicate\"] and queue.acknowledge(third, 101)\n        conflict = False\n        try:\n            apply(business, \"report-27\", 38)\n        except ValueError as error:\n            conflict = str(error) == \"same_business_id_different_intent\"\n        assert conflict\n        effects = business.execute(\"SELECT event_id,total FROM effects\").fetchall()\n        assert effects == [(\"report-27\", 37)]\n\n        queue.put(\"msg-renew\", \"report-28\", 9)\n        renewal = queue.receive(\"msg-renew\", 0)\n        assert queue.extend(renewal, 20, 30)\n        assert queue.receive(\"msg-renew\", 31) is None\n        after_renewal = queue.receive(\"msg-renew\", 51)\n        assert after_renewal[\"epoch\"] == 2\n        assert not queue.extend(renewal, 52, 30)\n        queue.db.close()\n        business.close()\n    print(json.dumps({\"clock\": \"controlled_integer_seconds_not_elapsed_cloud_time\",\n                      \"controlled_timeline\": timeline,\n                      \"first_receive\": first, \"second_receive\": second,\n                      \"old_worker_can_commit_after_visibility_expiry\": old_worker,\n                      \"new_worker_reuses_business_receipt\": new_worker,\n                      \"stale_ack_accepted\": stale_ack, \"current_ack_accepted\": current_ack,\n                      \"republished_transport_same_business\": replay, \"same_id_changed_intent_rejected\": conflict,\n                      \"effects\": effects, \"renewal\": {\"extended_at\": 20, \"new_visible_at\": 50,\n                                                       \"hidden_at_31\": True, \"next_receive_at\": 51,\n                                                       \"new_epoch\": after_renewal[\"epoch\"], \"stale_extend_rejected\": True},\n                      \"scope\": \"actual_SQLite_transactions_bounded_queue_reference_not_SQS_or_Lambda\",\n                      \"limits\": [\"visibility is not execution cancellation or effect fencing\",\n                                 \"strict stale ACK rejection is this reference contract, not SQS wire behavior\",\n                                 \"business effect and inbox share one local DB transaction; no remote API atomicity claim\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "batch_response_reference.py": "\"\"\"Declared A/B/C outcomes under bounded batch policies; no cloud function is invoked.\"\"\"\nimport json\n\n\ndef reference(partial_enabled=True, fifo=False, raises=False):\n    ids = [\"msg-A\", \"msg-B\", \"msg-C\"]\n    effects, failures, processed = [], [], []\n    stop = False\n    for identity in ids:\n        if stop:\n            failures.append(identity)\n            continue\n        processed.append(identity)\n        if identity == \"msg-B\":\n            failures.append(identity)\n            stop = fifo\n        else:\n            effects.append(identity)\n    response = {\"batchItemFailures\": [{\"itemIdentifier\": value} for value in failures]}\n    retries = ids if raises else failures if partial_enabled else []\n    acknowledged = [identity for identity in ids if identity not in retries]\n    return {\"partial_enabled\": partial_enabled, \"fifo_stop_after_failure\": fifo,\n            \"handler_raises_after_processing\": raises, \"processed\": processed,\n            \"effects\": effects, \"normal_response_if_returned\": response,\n            \"transport_retries\": retries, \"acknowledged\": acknowledged,\n            \"acknowledged_without_effect\": [identity for identity in acknowledged if identity not in effects]}\n\n\ndef main():\n    cases = {\"standard_partial\": reference(), \"partial_not_enabled\": reference(False),\n             \"handler_raises\": reference(raises=True), \"fifo_stop\": reference(fifo=True)}\n    assert cases[\"standard_partial\"][\"transport_retries\"] == [\"msg-B\"]\n    assert cases[\"standard_partial\"][\"effects\"] == [\"msg-A\", \"msg-C\"]\n    assert cases[\"partial_not_enabled\"][\"acknowledged_without_effect\"] == [\"msg-B\"]\n    assert cases[\"handler_raises\"][\"transport_retries\"] == [\"msg-A\", \"msg-B\", \"msg-C\"]\n    assert cases[\"fifo_stop\"][\"processed\"] == [\"msg-A\", \"msg-B\"]\n    assert cases[\"fifo_stop\"][\"transport_retries\"] == [\"msg-B\", \"msg-C\"]\n    assert cases[\"fifo_stop\"][\"effects\"] == [\"msg-A\"]\n    print(json.dumps({\"fixture\": \"declared_A_success_B_failure_C_success_or_unprocessed\",\n                      \"cases\": cases, \"scope\": \"bounded_policy_reference_not_Lambda_or_SQS_execution\",\n                      \"note\": \"Only the enabled mapping interprets the normal partial response; an exception fails the whole batch.\"},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "placement_reservations.py": "\"\"\"Finite placement search over declared slots, then actual two-process SQLite group reservation.\"\"\"\nfrom dataclasses import dataclass\nimport json\nimport multiprocessing as mp\nfrom pathlib import Path\nimport sqlite3\nimport tempfile\n\n\n@dataclass(frozen=True)\nclass Node:\n    name: str\n    gpu: int\n    cpu: int = 64\n    memory_gib: int = 256\n    flavor: str = \"A100-fixture\"\n    rack: str = \"rack-a\"\n\n\ndef place(nodes, workers, same_rack=False, first_fit=False):\n    remaining = [[n.gpu, n.cpu, n.memory_gib] for n in nodes]\n    assigned = []\n\n    def search(index):\n        if index == len(workers):\n            return list(assigned)\n        gpu = workers[index]\n        for i, node in enumerate(nodes):\n            if node.flavor != \"A100-fixture\" or any(a < b for a, b in zip(remaining[i], [gpu, 4, 8])):\n                continue\n            if same_rack and assigned and node.rack != nodes[assigned[0]].rack:\n                continue\n            remaining[i] = [a-b for a, b in zip(remaining[i], [gpu, 4, 8])]\n            assigned.append(i)\n            result = search(index+1)\n            if result is not None:\n                return result\n            assigned.pop()\n            remaining[i] = [a+b for a, b in zip(remaining[i], [gpu, 4, 8])]\n            if first_fit:\n                return None\n        return None\n\n    result = search(0)\n    return None if result is None else [nodes[i].name for i in result]\n\n\ndef quota(borrowing_limit):\n    used, nominal, request, available_lending = 12, 16, 16, 12\n    borrowed = max(0, used+request-nominal)\n    return {\"used_after\": used+request, \"borrow_required\": borrowed,\n            \"borrowing_limit\": borrowing_limit, \"lending_available\": available_lending,\n            \"quota_allowed\": borrowed <= min(borrowing_limit, available_lending)}\n\n\nclass InjectedFailure(Exception):\n    pass\n\n\ndef reserve(path, job, expected, inject=False):\n    db = sqlite3.connect(path, timeout=10, isolation_level=None)\n    try:\n        db.execute(\"BEGIN IMMEDIATE\")\n        current = dict(db.execute(\"SELECT name,version FROM nodes\"))\n        if current != expected:\n            db.rollback()\n            return \"stale_snapshot\"\n        if db.execute(\"SELECT used FROM quota\").fetchone()[0] + 16 > 16:\n            db.rollback()\n            return \"quota_blocked\"\n        for number, name in enumerate([\"node-1\", \"node-2\"]):\n            changed = db.execute(\"UPDATE nodes SET free=free-8,version=version+1 WHERE name=? AND free>=8 AND version=?\",\n                                 (name, expected[name])).rowcount\n            if changed != 1:\n                db.rollback()\n                return \"capacity_changed\"\n            if inject and number == 0:\n                raise InjectedFailure()\n            db.execute(\"INSERT INTO allocations VALUES(?,?,8)\", (job, name))\n        db.execute(\"UPDATE quota SET used=used+16\")\n        db.commit()\n        return \"admitted\"\n    except InjectedFailure:\n        db.rollback()\n        return \"injected_rollback\"\n    finally:\n        db.close()\n\n\ndef contender(path, job, expected, barrier, output):\n    try:\n        barrier.wait(timeout=10)\n        output.put({\"job\": job, \"result\": reserve(path, job, expected)})\n    except Exception as error:\n        output.put({\"job\": job, \"error\": type(error).__name__})\n\n\ndef inspect(path):\n    with sqlite3.connect(path) as db:\n        return {\"nodes\": [{\"name\": name, \"free\": free, \"version\": version}\n                          for name, free, version in db.execute(\"SELECT * FROM nodes ORDER BY name\")],\n                \"quota_used\": db.execute(\"SELECT used FROM quota\").fetchone()[0],\n                \"allocations\": [{\"job\": job, \"node\": node, \"gpu_slots\": slots}\n                                for job, node, slots in db.execute(\"SELECT * FROM allocations ORDER BY job,node\")]}\n\n\ndef main():\n    nodes = [Node(\"n1\", 8), Node(\"n2\", 4), Node(\"n3\", 4), Node(\"n4\", 0)]\n    finite = {\"free_gpu_slots\": [8, 4, 4, 0], \"workers_8_8\": place(nodes, [8, 8]),\n              \"workers_8_4_4\": place(nodes, [8, 4, 4]),\n              \"quota_borrow_8\": quota(8), \"quota_borrow_12\": quota(12),\n              \"greedy_4_then_8\": place([Node(\"n1\", 8), Node(\"n2\", 4)], [4, 8], first_fit=True),\n              \"search_4_then_8\": place([Node(\"n1\", 8), Node(\"n2\", 4)], [4, 8]),\n              \"rack_required\": place([Node(\"n1\", 8), Node(\"n2\", 8, rack=\"rack-b\")], [8, 8], same_rack=True),\n              \"rack_unconstrained\": place([Node(\"n1\", 8), Node(\"n2\", 8, rack=\"rack-b\")], [8, 8]),\n              \"wrong_flavor\": place([Node(\"n1\", 8, flavor=\"T4-fixture\")], [8]),\n              \"cpu_short\": place([Node(\"n1\", 8, cpu=2)], [8]),\n              \"memory_short\": place([Node(\"n1\", 8, memory_gib=4)], [8])}\n    assert finite[\"workers_8_8\"] is None and finite[\"workers_8_4_4\"] == [\"n1\", \"n2\", \"n3\"]\n    assert not finite[\"quota_borrow_8\"][\"quota_allowed\"] and finite[\"quota_borrow_12\"][\"quota_allowed\"]\n    assert finite[\"greedy_4_then_8\"] is None and finite[\"search_4_then_8\"] == [\"n2\", \"n1\"]\n    assert finite[\"rack_required\"] is None and finite[\"rack_unconstrained\"] == [\"n1\", \"n2\"]\n    assert all(finite[k] is None for k in [\"wrong_flavor\", \"cpu_short\", \"memory_short\"])\n    with tempfile.TemporaryDirectory(prefix=\"infra-reservation-\") as temporary:\n        path = str(Path(temporary) / \"reservations.db\")\n        with sqlite3.connect(path) as db:\n            db.executescript(\"CREATE TABLE nodes(name TEXT PRIMARY KEY,free INT CHECK(free>=0),version INT);\"\n                             \"INSERT INTO nodes VALUES('node-1',8,0),('node-2',8,0);\"\n                             \"CREATE TABLE allocations(job TEXT,node TEXT,gpu_slots INT,PRIMARY KEY(job,node));\"\n                             \"CREATE TABLE quota(used INT CHECK(used BETWEEN 0 AND 16)); INSERT INTO quota VALUES(0);\")\n        expected = {\"node-1\": 0, \"node-2\": 0}\n        before = inspect(path)\n        rollback = reserve(path, \"injected\", expected, True)\n        assert rollback == \"injected_rollback\" and inspect(path) == before\n        context = mp.get_context(\"spawn\")\n        barrier, output = context.Barrier(2), context.Queue()\n        processes = [context.Process(target=contender, args=(path, job, expected, barrier, output))\n                     for job in [\"job-X\", \"job-Y\"]]\n        try:\n            for process in processes:\n                process.start()\n            results = sorted([output.get(timeout=15) for _ in processes], key=lambda r: r[\"job\"])\n            for process in processes:\n                process.join(timeout=10)\n                assert not process.is_alive() and process.exitcode == 0\n        finally:\n            for process in processes:\n                if process.is_alive():\n                    process.terminate()\n                    process.join(timeout=5)\n            output.close()\n            output.join_thread()\n        after = inspect(path)\n        assert sorted(row[\"result\"] for row in results) == [\"admitted\", \"stale_snapshot\"]\n        assert [n[\"free\"] for n in after[\"nodes\"]] == [0, 0] and after[\"quota_used\"] == 16\n        assert len(after[\"allocations\"]) == 2 and len({a[\"job\"] for a in after[\"allocations\"]}) == 1\n    print(json.dumps({\"resource_kind\": \"declared_integer_gpu_slots_not_devices\", \"finite_search\": finite,\n                      \"group_reservation\": {\"injected_after_first_node\": rollback, \"rollback_state\": before,\n                                            \"contenders\": results, \"committed_state\": after},\n                      \"scope\": \"finite_reference_search_and_real_two_process_SQLite_transactions_not_Kueue_or_Kubernetes\",\n                      \"limits\": [\"search models only declared scalar resources, flavor and optional rack constraint\",\n                                 \"one DB transaction is not a multi-object Kubernetes API transaction\",\n                                 \"reservation does not prove device health, pod readiness or first training update\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "subprocess_limits.py": "\"\"\"Actual bounded POSIX child-process limits; this does not create a security sandbox.\"\"\"\nimport errno\nimport json\nimport os\nfrom pathlib import Path\nimport resource\nimport selectors\nimport signal\nimport subprocess\nimport sys\nimport tempfile\nimport time\n\n\ndef child(mode, directory):\n    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))\n    if mode == \"file_size\":\n        signal.signal(signal.SIGXFSZ, signal.SIG_IGN)\n        resource.setrlimit(resource.RLIMIT_FSIZE, (4096, 4096))\n        descriptor = os.open(str(Path(directory) / \"bounded.bin\"), os.O_CREAT | os.O_WRONLY, 0o600)\n        first, rejected = os.write(descriptor, b\"x\" * 6000), False\n        try:\n            os.write(descriptor, b\"x\")\n        except OSError as error:\n            rejected = error.errno == errno.EFBIG\n        os.close(descriptor)\n        print(json.dumps({\"first_write_bytes\": first, \"next_write_EFBIG\": rejected,\n                          \"file_size\": (Path(directory) / \"bounded.bin\").stat().st_size}))\n    elif mode == \"descriptors\":\n        resource.setrlimit(resource.RLIMIT_NOFILE, (64, 64))\n        opened, rejected = [], False\n        try:\n            for _ in range(200):\n                opened.append(os.open(os.devnull, os.O_RDONLY))\n        except OSError as error:\n            rejected = error.errno == errno.EMFILE\n        count = len(opened)\n        for descriptor in opened:\n            os.close(descriptor)\n        print(json.dumps({\"limit\": 64, \"opened_extra\": count, \"next_open_EMFILE\": rejected}))\n    elif mode == \"cpu\":\n        resource.setrlimit(resource.RLIMIT_CPU, (1, 2))\n        print(\"ready\", flush=True)\n        while True:\n            pass\n    elif mode == \"wall\":\n        signal.signal(signal.SIGTERM, signal.SIG_IGN)\n        print(\"ready\", flush=True)\n        time.sleep(30)\n    else:\n        raise ValueError(mode)\n\n\ndef run(mode, directory):\n    before = resource.getrusage(resource.RUSAGE_CHILDREN)\n    start = time.monotonic()\n    process = subprocess.Popen([sys.executable, \"-B\", str(Path(__file__).resolve()), \"--child\", mode, directory],\n                               env={\"PYTHONIOENCODING\": \"utf-8\"}, cwd=directory,\n                               stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                               text=True, close_fds=True, start_new_session=True)\n    forced = False\n    ready = False\n    try:\n        if mode in {\"cpu\", \"wall\"}:\n            with selectors.DefaultSelector() as selector:\n                selector.register(process.stdout, selectors.EVENT_READ)\n                if not selector.select(timeout=5):\n                    raise RuntimeError(\"child did not announce ready\")\n                ready = process.stdout.readline().strip() == \"ready\"\n                assert ready\n        # The wall budget starts after readiness, so a slow interpreter startup\n        # cannot turn the intended ignored-TERM case into a different signal path.\n        stdout, stderr = process.communicate(timeout=0.25 if mode == \"wall\" else 5)\n    except subprocess.TimeoutExpired:\n        os.killpg(process.pid, signal.SIGTERM)\n        try:\n            stdout, stderr = process.communicate(timeout=0.2)\n        except subprocess.TimeoutExpired:\n            forced = True\n            os.killpg(process.pid, signal.SIGKILL)\n            stdout, stderr = process.communicate(timeout=3)\n    finally:\n        if process.poll() is None:\n            os.killpg(process.pid, signal.SIGKILL)\n            process.wait(timeout=3)\n    elapsed = time.monotonic() - start\n    after = resource.getrusage(resource.RUSAGE_CHILDREN)\n    cpu = (after.ru_utime+after.ru_stime)-(before.ru_utime+before.ru_stime)\n    assert not stderr, stderr\n    result = {\"exit_code\": process.returncode, \"elapsed_wall_seconds\": elapsed,\n              \"child_cpu_seconds\": cpu, \"force_after_TERM_required\": forced}\n    if mode in {\"file_size\", \"descriptors\"}:\n        assert process.returncode == 0\n        result[\"output\"] = json.loads(stdout)\n    else:\n        assert ready and stdout.strip() == \"\"\n        result[\"ready_before_limit\"] = True\n        result[\"termination_signal\"] = signal.Signals(-process.returncode).name\n        if mode == \"wall\":\n            result[\"wall_budget_from_ready_seconds\"] = 0.25\n            result[\"term_grace_seconds\"] = 0.2\n    return result\n\n\ndef main():\n    if os.name != \"posix\":\n        raise RuntimeError(\"POSIX child process and resource support required\")\n    with tempfile.TemporaryDirectory(prefix=\"infra-limits-\") as temporary:\n        results = {mode: run(mode, temporary) for mode in [\"file_size\", \"descriptors\", \"cpu\", \"wall\"]}\n    assert results[\"file_size\"][\"output\"] == {\"first_write_bytes\": 4096, \"next_write_EFBIG\": True, \"file_size\": 4096}\n    assert results[\"descriptors\"][\"output\"][\"next_open_EMFILE\"]\n    assert 0 < results[\"descriptors\"][\"output\"][\"opened_extra\"] < 64\n    assert results[\"cpu\"][\"termination_signal\"] in {\"SIGXCPU\", \"SIGKILL\"}\n    assert results[\"wall\"][\"termination_signal\"] == \"SIGKILL\" and results[\"wall\"][\"force_after_TERM_required\"]\n    assert results[\"wall\"][\"child_cpu_seconds\"] < 0.5\n    print(json.dumps({\"os\": sys.platform, \"cases\": results,\n                      \"scope\": \"actual_POSIX_limits_in_owned_children_not_container_or_kernel_isolation\",\n                      \"limits\": [\"RLIMIT_CPU is process CPU time, not wall time or cgroup bandwidth\",\n                                 \"RLIMIT_FSIZE bounds one file, not total temporary-disk usage\",\n                                 \"RLIMIT_NOFILE bounds descriptors, not process count\",\n                                 \"children use the same UID and may still access that UID's files/network\",\n                                 \"only owned child process groups are signaled; host limits are unchanged\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) > 1 and sys.argv[1] == \"--child\":\n        child(sys.argv[2], sys.argv[3])\n    else:\n        main()\n", "descriptors_and_paths.py": "\"\"\"Synthetic canaries: inherited authority, same-UID access, and single-leaf no-follow opening.\"\"\"\nimport errno\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport tempfile\n\n\ndef child(descriptor, path):\n    try:\n        os.read(descriptor, 128)\n        inherited = True\n    except OSError as error:\n        if error.errno != errno.EBADF:\n            raise\n        inherited = False\n    # Explicitly demonstrate that launch hygiene does not isolate the filesystem.\n    by_path = Path(path).read_text() == \"FAKE-CANARY-no-production-permission\"\n    print(json.dumps({\"fixture_environment_present\": \"LAB_DEMO_SECRET\" in os.environ,\n                      \"inherited_descriptor_readable\": inherited,\n                      \"same_uid_fixture_still_readable_by_path\": by_path}))\n\n\ndef main():\n    if os.name != \"posix\" or os.open not in os.supports_dir_fd or not hasattr(os, \"O_NOFOLLOW\"):\n        raise RuntimeError(\"POSIX openat/dir_fd and O_NOFOLLOW required\")\n    with tempfile.TemporaryDirectory(prefix=\"infra-descriptors-\") as temporary:\n        root = Path(temporary)\n        canary = root / \"canary.txt\"\n        canary.write_text(\"FAKE-CANARY-no-production-permission\")\n        descriptor = os.open(str(canary), os.O_RDONLY)\n        os.set_inheritable(descriptor, True)  # Deliberately undo the safe default for the counterexample.\n        try:\n            outputs = {}\n            for name, close_fds, env in [\n                    (\"explicit_unsafe_inheritance\", False, {\"LAB_DEMO_SECRET\": \"FAKE\", \"PYTHONIOENCODING\": \"utf-8\"}),\n                    (\"minimal_launch\", True, {\"PYTHONIOENCODING\": \"utf-8\"})]:\n                os.lseek(descriptor, 0, os.SEEK_SET)\n                result = subprocess.run([sys.executable, \"-B\", str(Path(__file__).resolve()), \"--child\", str(descriptor), str(canary)],\n                                        env=env, cwd=root, close_fds=close_fds,\n                                        capture_output=True, text=True, timeout=5, check=True)\n                outputs[name] = json.loads(result.stdout)\n        finally:\n            os.close(descriptor)\n        assert outputs[\"explicit_unsafe_inheritance\"] == {\"fixture_environment_present\": True,\n                 \"inherited_descriptor_readable\": True, \"same_uid_fixture_still_readable_by_path\": True}\n        assert outputs[\"minimal_launch\"] == {\"fixture_environment_present\": False,\n                 \"inherited_descriptor_readable\": False, \"same_uid_fixture_still_readable_by_path\": True}\n\n        allowed = root / \"work\"\n        allowed.mkdir()\n        outside = root / \"outside.txt\"\n        outside.write_text(\"fixture-B\")\n        leaf = allowed / \"report.txt\"\n        leaf.write_text(\"fixture-A\")\n        # Deterministic interleaving: check, replace, then use. No live race is required.\n        prefix_check = str(leaf).startswith(str(allowed))\n        leaf.unlink()\n        leaf.symlink_to(outside)\n        vulnerable_read = leaf.read_text()\n        directory_fd = os.open(str(allowed), os.O_RDONLY | getattr(os, \"O_DIRECTORY\", 0))\n        refused = False\n        try:\n            try:\n                file_fd = os.open(\"report.txt\", os.O_RDONLY | os.O_NOFOLLOW, dir_fd=directory_fd)\n            except OSError as error:\n                refused = error.errno in {errno.ELOOP, errno.EMLINK}\n            else:\n                os.close(file_fd)\n            leaf.unlink()\n            leaf.write_text(\"fixture-A\")\n            file_fd = os.open(\"report.txt\", os.O_RDONLY | os.O_NOFOLLOW, dir_fd=directory_fd)\n            try:\n                safe_value = os.read(file_fd, 128).decode()\n            finally:\n                os.close(file_fd)\n        finally:\n            os.close(directory_fd)\n        assert prefix_check and vulnerable_read == \"fixture-B\" and refused and safe_value == \"fixture-A\"\n    print(json.dumps({\"launch\": outputs, \"single_leaf_path\": {\"prefix_check_passed\": prefix_check,\n                      \"after_check_symlink_read\": vulnerable_read, \"no_follow_rejected_symlink\": refused,\n                      \"normal_leaf_read\": safe_value},\n                      \"scope\": \"actual_POSIX_children_and_fixture_files_not_a_security_sandbox\",\n                      \"limits\": [\"Python defaults already make new FDs non-inheritable and Popen close_fds=True; unsafe case explicitly changes them\",\n                                 \"no-follow example accepts only one fixed leaf under a trusted already-open directory\",\n                                 \"does not secure arbitrary multi-component paths, hard links, untrusted mounts or directory permissions\",\n                                 \"same-UID child still reads fixture by path; no filesystem or network isolation claim\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) > 1 and sys.argv[1] == \"--child\":\n        child(int(sys.argv[2]), sys.argv[3])\n    else:\n        main()\n"};
