// storage-parallel-acceptance-files.js
const storageParallelFiles={"shard_range.py": "\"\"\"Bounded local HTTP: complete shards versus indexed byte ranges.\n\nThis is a teaching HTTP subset, not an S3 client/server or a storage benchmark.\n\"\"\"\nimport argparse\nfrom copy import deepcopy\nimport hashlib\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nimport json\nfrom pathlib import Path\nimport platform\nimport re\nimport threading\nfrom urllib.error import HTTPError\nfrom urllib.request import Request, urlopen\n\n\ndef digest(data):\n    return hashlib.sha256(data).hexdigest()\n\n\ndef build_inputs():\n    samples = [(\"sample-%02d:\" % i).encode().ljust(64, b\".\") for i in range(20)]\n    objects = {\"shard-%d\" % i: b\"\".join(samples[i*4:i*4+4]) for i in range(5)}\n    manifest = {\"version\": \"data-v1\", \"samples\": {}}\n    for i, value in enumerate(samples):\n        key = \"shard-%d\" % (i // 4)\n        manifest[\"samples\"][i] = {\"key\": key, \"offset\": (i % 4)*64,\n            \"length\": 64, \"object_length\": 256,\n            \"object_sha256\": digest(objects[key]), \"sample_sha256\": digest(value)}\n    return samples, objects, manifest\n\n\nclass Handler(BaseHTTPRequestHandler):\n    protocol_version = \"HTTP/1.1\"\n\n    def log_message(self, *_):\n        pass\n\n    def do_GET(self):\n        key = self.path.removeprefix(\"/\")\n        with self.server.lock:\n            payload = self.server.objects.get(key)\n            self.server.requests.append({\"key\": key, \"range\": self.headers.get(\"Range\")})\n        if payload is None:\n            self.send_error(404)\n            return\n        etag = '\"' + digest(payload) + '\"'  # This fixture's rule, not an S3 ETag rule.\n        if self.headers.get(\"If-Match\") not in (None, etag):\n            self.send_error(412)\n            return\n        status, body, content_range = 200, payload, None\n        requested = self.headers.get(\"Range\")\n        if requested is not None:\n            match = re.fullmatch(r\"bytes=(\\d+)-(\\d+)\", requested)\n            if not match:\n                self.send_error(400)\n                return\n            start, end = map(int, match.groups())\n            if not 0 <= start <= end < len(payload):\n                self.send_error(416)\n                return\n            status, body = 206, payload[start:end+1]\n            content_range = \"bytes %d-%d/%d\" % (start, end, len(payload))\n        self.send_response(status)\n        self.send_header(\"Content-Type\", \"application/octet-stream\")\n        self.send_header(\"Content-Length\", str(len(body)))\n        self.send_header(\"ETag\", etag)\n        if content_range:\n            self.send_header(\"Content-Range\", content_range)\n        self.end_headers()\n        self.wfile.write(body)\n\n\ndef fetch(base, entry, ranged):\n    start, end = entry[\"offset\"], entry[\"offset\"] + entry[\"length\"] - 1\n    headers = {\"If-Match\": '\"' + entry[\"object_sha256\"] + '\"'}\n    if ranged:\n        headers[\"Range\"] = \"bytes=%d-%d\" % (start, end)\n    with urlopen(Request(base + \"/\" + entry[\"key\"], headers=headers), timeout=3) as response:\n        expected = entry[\"length\"] if ranged else entry[\"object_length\"]\n        body = response.read(expected + 1)\n        assert len(body) == expected and int(response.headers[\"Content-Length\"]) == expected\n        assert response.status == (206 if ranged else 200)\n        if ranged:\n            assert response.headers[\"Content-Range\"] == \"bytes %d-%d/%d\" % (start, end, entry[\"object_length\"])\n        else:\n            assert digest(body) == entry[\"object_sha256\"]\n        return body\n\n\ndef select_samples(base, manifest, selected, ranged):\n    cache, output, requests, transferred = {}, [], 0, 0\n    for sample_id in selected:\n        entry = manifest[\"samples\"][sample_id]\n        if ranged:\n            sample = fetch(base, entry, True)\n            requests += 1\n            transferred += len(sample)\n        else:\n            key = entry[\"key\"]\n            if key not in cache:\n                cache[key] = fetch(base, entry, False)\n                requests += 1\n                transferred += len(cache[key])\n            sample = cache[key][entry[\"offset\"]:entry[\"offset\"]+entry[\"length\"]]\n        if len(sample) != entry[\"length\"] or digest(sample) != entry[\"sample_sha256\"]:\n            raise ValueError(\"sample_digest_mismatch\")\n        output.append(sample)\n    return output, {\"requests\": requests, \"body_bytes\": transferred,\n        \"useful_sample_bytes\": sum(map(len, output))}\n\n\ndef exercise():\n    samples, objects, manifest = build_inputs()\n    server = ThreadingHTTPServer((\"127.0.0.1\", 0), Handler)\n    server.daemon_threads = True\n    server.objects, server.lock, server.requests = objects, threading.Lock(), []\n    thread = threading.Thread(target=server.serve_forever, kwargs={\"poll_interval\": 0.01}, daemon=True)\n    thread.start()\n    base = \"http://127.0.0.1:%d\" % server.server_port\n    selected = [0, 1, 6, 7, 17]\n    try:\n        full, full_metrics = select_samples(base, manifest, selected, False)\n        ranged, range_metrics = select_samples(base, manifest, selected, True)\n        assert full == ranged == [samples[i] for i in selected]\n        assert full_metrics == {\"requests\": 3, \"body_bytes\": 768, \"useful_sample_bytes\": 320}\n        assert range_metrics == {\"requests\": 5, \"body_bytes\": 320, \"useful_sample_bytes\": 320}\n        with server.lock:\n            positive_requests = deepcopy(server.requests)\n        assert len(positive_requests) == 8\n        assert all(row[\"range\"] is None for row in positive_requests[:3])\n        assert all(row[\"range\"] is not None for row in positive_requests[3:])\n\n        # Keep the old manifest, then replace one object's bytes.\n        with server.lock:\n            original = server.objects[\"shard-0\"]\n            server.objects[\"shard-0\"] = b\"!\" + original[1:]\n        try:\n            select_samples(base, manifest, [0], True)\n            raise AssertionError(\"changed object accepted\")\n        except HTTPError as error:\n            assert error.code == 412\n            error.close()\n        with server.lock:\n            server.objects[\"shard-0\"] = original\n\n        wrong_index = deepcopy(manifest)\n        wrong_index[\"samples\"][0][\"offset\"] = 64\n        try:\n            select_samples(base, wrong_index, [0], True)\n            raise AssertionError(\"wrong index accepted\")\n        except ValueError as error:\n            assert str(error) == \"sample_digest_mismatch\"\n\n        invalid = dict(manifest[\"samples\"][0], offset=250, length=64)\n        try:\n            fetch(base, invalid, True)\n            raise AssertionError(\"out-of-range read accepted\")\n        except HTTPError as error:\n            assert error.code == 416\n            error.close()\n    finally:\n        server.shutdown()\n        server.server_close()\n        thread.join(2)\n        assert not thread.is_alive()\n\n    # Independent input model from the chapter, not timings measured by this server.\n    total_bytes = 10000 * 64 * 1024\n    bandwidth = 125 * 1024 * 1024\n    transfer_s = total_bytes / bandwidth\n    separate_s = 10000 * 0.005 + transfer_s\n    shard_s = 100 * 0.005 + transfer_s\n    assert total_bytes == 625 * 1024 * 1024\n    assert (transfer_s, separate_s, shard_s) == (5, 55, 5.5)\n    return {\"status\": \"passed\", \"python\": platform.python_version(),\n        \"source_sha256\": digest(Path(__file__).read_bytes()),\n        \"input\": {\"samples\": 20, \"sample_bytes\": 64, \"samples_per_shard\": 4, \"selected_ids\": selected},\n        \"full_shards_with_request_cache\": full_metrics, \"indexed_ranges\": range_metrics,\n        \"server_positive_requests\": positive_requests,\n        \"negative_probes\": {\"object_changed\": 412, \"wrong_offset\": \"sample_digest_mismatch\", \"out_of_bounds\": 416},\n        \"declared_serial_cost_model\": {\"samples\": 10000, \"sample_kib\": 64,\n            \"total_mib\": 625, \"bandwidth_mib_s\": 125, \"request_ms\": 5,\n            \"separate_s\": separate_s, \"shards_s\": shard_s},\n        \"scope\": \"Actual bounded loopback HTTP and byte checks; cost seconds are declared serial arithmetic, not measured latency. No S3, cloud storage, compression or GPU executed.\"}\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--report\", type=Path)\n    args = parser.parse_args()\n    result = exercise()\n    text = json.dumps(result, ensure_ascii=False, indent=2) + \"\\n\"\n    if args.report:\n        args.report.write_text(text)\n    print(text, end=\"\")\n", "tp_forward_backward.py": "\"\"\"Two actual CPU/Gloo ranks: manually make tensor-parallel chain rules explicit.\n\nAutograd is local. Ordinary collectives are deliberately outside its graph.\nThis is not a production tensor-parallel layer or a performance benchmark.\n\"\"\"\nimport argparse\nfrom datetime import timedelta\nimport hashlib\nimport json\nfrom pathlib import Path\nimport platform\nimport tempfile\nimport time\n\nimport torch\nimport torch.distributed as dist\nimport torch.multiprocessing as mp\n\n\nX = [[1., 2.]]\nW = [[1., 0., 2., 0.], [0., 1., 0., 2.]]\nU = [[1., 0.], [0., 1.], [1., 1.], [2., 0.]]\nBIAS = [1., 1.]\nTARGET = [[3., -1.]]\nLR = 0.01\n\n\ndef tensor(value, grad=False):\n    return torch.tensor(value, dtype=torch.float64, requires_grad=grad)\n\n\ndef baseline():\n    x, w, u, bias = tensor(X, True), tensor(W, True), tensor(U, True), tensor(BIAS, True)\n    y = torch.relu(x @ w) @ u + bias\n    loss = ((y - tensor(TARGET))**2).sum() / 2\n    loss.backward()\n    return {\"y\": y.detach().tolist(), \"loss\": loss.item(),\n        \"dx\": x.grad.tolist(), \"dw\": w.grad.tolist(), \"du\": u.grad.tolist(), \"db\": bias.grad.tolist(),\n        \"w_after\": (w - LR*w.grad).detach().tolist(),\n        \"u_after\": (u - LR*u.grad).detach().tolist(),\n        \"bias_after\": (bias - LR*bias.grad).detach().tolist()}\n\n\ndef worker(rank, rendezvous, folder):\n    torch.set_num_threads(1)\n    dist.init_process_group(\"gloo\", init_method=rendezvous, rank=rank, world_size=2,\n                            timeout=timedelta(seconds=15))\n    try:\n        start = rank*2\n        x = tensor(X, True)\n        w = tensor([row[start:start+2] for row in W], True)\n        u = tensor(U[start:start+2], True)\n        hidden = torch.relu(x @ w)\n        partial = hidden @ u\n        with torch.no_grad():\n            y = partial.detach().clone()\n            dist.all_reduce(y, op=dist.ReduceOp.SUM)\n            y += tensor(BIAS)  # Add once after summing the two partial outputs.\n            dy = y - tensor(TARGET)  # d(0.5 * sum((Y-target)^2))/dY\n        partial.backward(dy)  # Local autograd receives the explicit shared output gradient.\n        dx_local = x.grad.detach().clone()\n        dx = dx_local.clone()\n        dist.all_reduce(dx, op=dist.ReduceOp.SUM)\n\n        # Actual reduction of the deliberately wrong bias placement.\n        bad_y = partial.detach() + tensor(BIAS)\n        dist.all_reduce(bad_y, op=dist.ReduceOp.SUM)\n        result = {\"rank\": rank, \"w_shape\": list(w.shape), \"u_shape\": list(u.shape),\n            \"hidden\": hidden.detach().tolist(), \"partial_output\": partial.detach().tolist(),\n            \"y\": y.tolist(), \"dy\": dy.tolist(), \"dx_partial\": dx_local.tolist(), \"dx\": dx.tolist(),\n            \"dw\": w.grad.tolist(), \"du\": u.grad.tolist(), \"db\": dy.sum(dim=0).tolist(),\n            \"w_after\": (w - LR*w.grad).detach().tolist(), \"u_after\": (u - LR*u.grad).detach().tolist(),\n            \"bias_after\": (tensor(BIAS) - LR*dy.sum(dim=0)).tolist(), \"wrong_bias_y\": bad_y.tolist()}\n        Path(folder, \"rank-%d.json\" % rank).write_text(json.dumps(result))\n    finally:\n        dist.destroy_process_group()\n\n\ndef close(actual, expected):\n    torch.testing.assert_close(tensor(actual), tensor(expected), rtol=0, atol=1e-12)\n\n\ndef exercise():\n    reference = baseline()\n    # Hand-computed oracle, independent of the full autograd baseline.\n    expected_dw = [[9, 6, 15, 18], [18, 12, 30, 36]]\n    expected_du = [[9, 6], [18, 12], [18, 12], [36, 24]]\n    assert reference[\"y\"] == [[12, 5]] and reference[\"loss\"] == 58.5\n    assert reference[\"dx\"] == [[39, 42]] and reference[\"db\"] == [9, 6]\n    assert reference[\"dw\"] == expected_dw and reference[\"du\"] == expected_du\n    with tempfile.TemporaryDirectory(prefix=\"tp-chain-rule-\") as folder:\n        rendezvous = Path(folder, \"rendezvous\").as_uri()  # File must not already exist.\n        context = mp.spawn(worker, args=(rendezvous, folder), nprocs=2, join=False)\n        deadline = time.monotonic() + 45\n        try:\n            while not context.join(timeout=1):\n                if time.monotonic() > deadline:\n                    raise TimeoutError(\"trusted TP children exceeded 45 seconds\")\n        finally:\n            for child in context.processes:\n                if child.is_alive():\n                    child.terminate()\n            for child in context.processes:\n                child.join(2)\n                if child.is_alive():\n                    child.kill()\n                    child.join(2)\n        results = [json.loads(Path(folder, \"rank-%d.json\" % r).read_text()) for r in range(2)]\n    for r, local in enumerate(results):\n        start = r*2\n        close(local[\"y\"], reference[\"y\"])\n        close(local[\"dx\"], reference[\"dx\"])\n        close(local[\"dw\"], [row[start:start+2] for row in reference[\"dw\"]])\n        close(local[\"du\"], reference[\"du\"][start:start+2])\n        close(local[\"db\"], reference[\"db\"])\n        close(local[\"w_after\"], [row[start:start+2] for row in reference[\"w_after\"]])\n        close(local[\"u_after\"], reference[\"u_after\"][start:start+2])\n        close(local[\"bias_after\"], reference[\"bias_after\"])\n        assert local[\"wrong_bias_y\"] == [[13, 6]]\n    assert [r[\"dx_partial\"] for r in results] == [[[9, 6]], [[30, 36]]]\n    nonlinear_parts = tensor([1, -2])\n    sum_then_relu = torch.relu(nonlinear_parts.sum()).item()\n    relu_then_sum = torch.relu(nonlinear_parts).sum().item()\n    assert sum_then_relu == 0 and relu_then_sum == 1\n    return {\"status\": \"passed\", \"python\": platform.python_version(), \"torch\": torch.__version__,\n        \"backend\": \"gloo\", \"world_size\": 2, \"device\": \"cpu\", \"dtype\": \"float64\",\n        \"source_sha256\": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n        \"reference\": reference, \"ranks\": results,\n        \"wrong_nonlinearity\": {\"partials\": [1, -2], \"sum_then_relu\": sum_then_relu, \"relu_then_sum\": relu_then_sum},\n        \"scope\": \"Actual two-rank forward SUM, input-gradient SUM and wrong-bias SUM. Local autograd with explicit dY; no automatic distributed-autograd layer, GPU/NCCL, multi-host, model quality or performance claim.\"}\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--report\", type=Path)\n    args = parser.parse_args()\n    result = exercise()\n    text = json.dumps(result, ensure_ascii=False, indent=2) + \"\\n\"\n    if args.report:\n        args.report.write_text(text)\n    print(text, end=\"\")\n", "acceptance_record.py": "\"\"\"Check a read-only task record against a SEPARATE tester-owned contract.\n\nFixture consistency only: this program does not call or attest Kairo, a model,\nan identity service, or the provenance/authenticity of an exported record.\n\"\"\"\nimport argparse\nfrom copy import deepcopy\nimport hashlib\nimport json\nfrom pathlib import Path\nimport platform\n\n\ndef fingerprint(value):\n    data = json.dumps(value, sort_keys=True, separators=(\",\", \":\"), ensure_ascii=False).encode()\n    return hashlib.sha256(data).hexdigest()\n\n\ndef examples():\n    request = {\"request_id\": \"R1\", \"tenant\": \"A\", \"action\": \"read_summary\",\n        \"resource\": \"reports-A\", \"delivery\": \"session-17\", \"source_version\": \"A-v1\"}\n    contract = {\"format\": \"readonly-contract-v1\", \"case_id\": \"readonly-A\",\n        \"request\": request, \"principal\": \"fixture-A\",\n        \"events\": {\"A-e1\": 5, \"A-e2\": 7, \"A-e3\": 11}, \"minimum_citations\": 2,\n        \"B_before\": {\"version\": 7, \"sha256\": fingerprint({\"sentinel\": \"B-original\"})}}\n    evidence = {\"format\": \"readonly-evidence-v1\", \"case_id\": \"readonly-A\",\n        \"source\": \"teaching_fixture\", \"target_version\": None,\n        \"submissions\": [\n            {\"transport_id\": \"q0\", \"request_id\": \"R1\", \"args_sha256\": fingerprint(request), \"task_id\": \"T1\", \"ack\": \"lost\"},\n            {\"transport_id\": \"q1\", \"request_id\": \"R1\", \"args_sha256\": fingerprint(request), \"task_id\": \"T1\", \"ack\": \"received\"}],\n        \"authoritative_task\": {\"task_id\": \"T1\", \"status\": \"SUCCEEDED\"},\n        \"tool_receipts\": [\n            {\"attempt_id\": \"a0\", \"principal\": \"fixture-A\", \"tenant\": \"A\", \"action\": \"read\",\n             \"resource\": \"reports-A\", \"status\": \"success\", \"source_version\": \"A-v1\",\n             \"events\": {\"A-e1\": 5, \"A-e2\": 7, \"A-e3\": 11}},\n            {\"attempt_id\": \"a1\", \"principal\": \"fixture-A\", \"tenant\": \"B\", \"action\": \"write\",\n             \"resource\": \"reports-B\", \"status\": \"denied\", \"events\": {}}],\n        \"B_before\": deepcopy(contract[\"B_before\"]), \"B_after\": deepcopy(contract[\"B_before\"]),\n        \"business_writes\": [],\n        \"delivery\": {\"task_id\": \"T1\", \"channel\": \"session-17\", \"total\": 23,\n                     \"citations\": [\"A-e1\", \"A-e3\"]}}\n    return contract, evidence\n\n\ndef validate(contract, evidence):\n    errors = []\n    if not isinstance(contract, dict) or contract.get(\"format\") != \"readonly-contract-v1\":\n        return [\"contract_format\"]\n    if not isinstance(evidence, dict) or evidence.get(\"format\") != \"readonly-evidence-v1\":\n        return [\"evidence_format\"]\n    # The tester supplies this contract, not the model or its proposed result.\n    required = [\"case_id\", \"request\", \"principal\", \"events\", \"minimum_citations\", \"B_before\"]\n    if any(key not in contract for key in required):\n        return [\"contract_missing_field\"]\n    request, events = contract[\"request\"], contract[\"events\"]\n    if (not isinstance(request, dict) or not isinstance(events, dict) or not events\n            or any(not isinstance(k, str) or type(v) is not int for k, v in events.items())\n            or type(contract[\"minimum_citations\"]) is not int\n            or not 1 <= contract[\"minimum_citations\"] <= len(events)):\n        return [\"contract_types\"]\n    if not all(isinstance(request.get(k), str) and request[k] for k in\n               [\"request_id\", \"tenant\", \"action\", \"resource\", \"delivery\", \"source_version\"]):\n        return [\"request_types\"]\n    if request[\"action\"] != \"read_summary\":\n        return [\"unsupported_contract_action\"]\n    if evidence.get(\"case_id\") != contract[\"case_id\"]:\n        errors.append(\"case_mismatch\")\n    source = evidence.get(\"source\")\n    if source not in [\"teaching_fixture\", \"target_export\"]:\n        errors.append(\"unknown_record_source\")\n    version = evidence.get(\"target_version\")\n    if source == \"target_export\" and (not isinstance(version, str) or version.strip() in [\"\", \"pending\", \"待接入\", \"待验收\"]):\n        errors.append(\"unbound_target_version\")\n\n    submissions = evidence.get(\"submissions\")\n    if not isinstance(submissions, list) or not submissions or any(not isinstance(row, dict) for row in submissions):\n        return errors + [\"submissions_type\"]\n    tasks = [row.get(\"task_id\") for row in submissions]\n    task_ids = {value for value in tasks if isinstance(value, str) and value}\n    if len(task_ids) != 1 or any(not isinstance(value, str) or not value for value in tasks):\n        errors.append(\"logical_task_count\")\n    expected_digest = fingerprint(request)\n    if any(row.get(\"request_id\") != request[\"request_id\"] or row.get(\"args_sha256\") != expected_digest for row in submissions):\n        errors.append(\"request_identity_or_arguments\")\n    transports = [row.get(\"transport_id\") for row in submissions]\n    if any(not isinstance(v, str) or not v for v in transports) or len(set(transports)) != len(transports):\n        errors.append(\"transport_identity\")\n\n    authoritative = evidence.get(\"authoritative_task\", {})\n    delivery = evidence.get(\"delivery\", {})\n    if not isinstance(authoritative, dict) or not isinstance(delivery, dict):\n        return errors + [\"result_type\"]\n    if not isinstance(authoritative.get(\"task_id\"), str) or authoritative.get(\"task_id\") not in task_ids or authoritative.get(\"status\") != \"SUCCEEDED\":\n        errors.append(\"not_completed_original_task\")\n    if not isinstance(delivery.get(\"task_id\"), str) or delivery.get(\"task_id\") not in task_ids or delivery.get(\"channel\") != request[\"delivery\"]:\n        errors.append(\"wrong_delivery_task_or_channel\")\n    if type(delivery.get(\"total\")) is not int or delivery[\"total\"] != sum(events.values()):\n        errors.append(\"wrong_business_total\")\n\n    receipts = evidence.get(\"tool_receipts\")\n    if not isinstance(receipts, list) or any(not isinstance(row, dict) for row in receipts):\n        return errors + [\"receipts_type\"]\n    observed, attempt_ids = {}, []\n    for receipt in receipts:\n        attempt = receipt.get(\"attempt_id\")\n        if not isinstance(attempt, str) or not attempt:\n            errors.append(\"attempt_identity\")\n        else:\n            attempt_ids.append(attempt)\n        if receipt.get(\"status\") == \"denied\":\n            if receipt.get(\"events\") not in [None, {}]:\n                errors.append(\"denied_payload_leak\")\n            continue\n        if receipt.get(\"status\") != \"success\":\n            errors.append(\"unknown_receipt_status\")\n            continue\n        if any(receipt.get(key) != expected for key, expected in\n               [(\"principal\", contract[\"principal\"]), (\"tenant\", request[\"tenant\"]),\n                (\"action\", \"read\"), (\"resource\", request[\"resource\"]),\n                (\"source_version\", request[\"source_version\"])]):\n            errors.append(\"unauthorized_or_wrong_source_read\")\n            continue\n        data = receipt.get(\"events\")\n        if not isinstance(data, dict) or any(key not in events or type(value) is not int or value != events[key] for key, value in data.items()):\n            errors.append(\"wrong_source_values\")\n            continue\n        observed.update(data)\n    if len(set(attempt_ids)) != len(attempt_ids):\n        errors.append(\"duplicate_attempt_identity\")\n    if observed != events:\n        errors.append(\"missing_allowed_read\")\n    citations = delivery.get(\"citations\")\n    if (not isinstance(citations, list) or any(not isinstance(v, str) for v in citations)\n            or len(set(citations)) < contract[\"minimum_citations\"]\n            or any(v not in observed for v in citations)):\n        errors.append(\"unsupported_citations\")\n    if evidence.get(\"B_before\") != contract[\"B_before\"] or evidence.get(\"B_after\") != contract[\"B_before\"]:\n        errors.append(\"forbidden_snapshot_changed\")\n    if evidence.get(\"business_writes\") != []:\n        errors.append(\"readonly_task_wrote\")\n    return sorted(set(errors))\n\n\ndef exercise():\n    contract, evidence = examples()\n    assert validate(contract, evidence) == []\n    cases = []\n\n    def rejects(name, change, expected):\n        candidate = deepcopy(evidence)\n        change(candidate)\n        errors = validate(contract, candidate)\n        assert expected in errors, (name, errors)\n        cases.append({\"case\": name, \"expected_error\": expected, \"actual_errors\": errors})\n\n    rejects(\"all_denied_but_plausible_answer\", lambda e: e.update(tool_receipts=[]), \"missing_allowed_read\")\n    rejects(\"unchanged_B_because_nothing_ran\", lambda e: e[\"authoritative_task\"].update(status=\"RUNNING\"), \"not_completed_original_task\")\n    rejects(\"same_B_content_new_version\", lambda e: e[\"B_after\"].update(version=8), \"forbidden_snapshot_changed\")\n    rejects(\"wrong_sum_with_valid_citations\", lambda e: e[\"delivery\"].update(total=38), \"wrong_business_total\")\n    rejects(\"citation_from_other_tenant\", lambda e: e[\"delivery\"].update(citations=[\"A-e1\", \"B-e1\"]), \"unsupported_citations\")\n    rejects(\"retry_created_another_task\", lambda e: e[\"submissions\"][1].update(task_id=\"T2\"), \"logical_task_count\")\n    rejects(\"same_request_changed_arguments\", lambda e: e[\"submissions\"][1].update(args_sha256=\"0\"*64), \"request_identity_or_arguments\")\n    rejects(\"target_version_still_pending\", lambda e: e.update(source=\"target_export\", target_version=\"待接入\"), \"unbound_target_version\")\n    rejects(\"denied_call_returns_private_payload\", lambda e: e[\"tool_receipts\"][1].update(events={\"B-e1\": 999}), \"denied_payload_leak\")\n    rejects(\"readonly_task_writes_A\", lambda e: e.update(business_writes=[{\"tenant\": \"A\", \"action\": \"write\"}]), \"readonly_task_wrote\")\n    assert len(cases) == 10\n    return {\"status\": \"passed\", \"python\": platform.python_version(),\n        \"source_sha256\": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n        \"positive\": {\"record_consistent\": True, \"source\": \"teaching_fixture\", \"provenance_verified\": False,\n                     \"request_transports\": 2, \"logical_tasks\": 1, \"total\": 23},\n        \"negative_probes\": cases,\n        \"scope\": \"Checks declared fixture records against a separate tester-owned contract. No Kairo/model/tool backend called; consistency does not attest record provenance or real target behavior.\"}\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--contract\", type=Path)\n    parser.add_argument(\"--evidence\", type=Path)\n    parser.add_argument(\"--report\", type=Path)\n    parser.add_argument(\"--write-examples\", type=Path)\n    args = parser.parse_args()\n    if bool(args.contract) != bool(args.evidence):\n        parser.error(\"--contract and --evidence must be supplied together\")\n    if args.write_examples:\n        args.write_examples.mkdir(parents=True, exist_ok=True)\n        for name, item in zip([\"readonly-contract.example.json\", \"readonly-evidence.example.json\"], examples()):\n            (args.write_examples/name).write_text(json.dumps(item, ensure_ascii=False, indent=2)+\"\\n\")\n    if args.contract:\n        for file in [args.contract, args.evidence]:\n            if file.stat().st_size > 1024*1024:\n                parser.error(\"example input must be at most 1 MiB\")\n        contract = json.loads(args.contract.read_text())\n        evidence = json.loads(args.evidence.read_text())\n        errors = validate(contract, evidence)\n        result = {\"status\": \"record_rejected\" if errors else \"record_consistent\", \"errors\": errors,\n                  \"provenance_verified\": False, \"source\": evidence.get(\"source\") if isinstance(evidence, dict) else None}\n    else:\n        result = exercise()\n    text = json.dumps(result, ensure_ascii=False, indent=2)+\"\\n\"\n    if args.report:\n        args.report.write_text(text)\n    print(text, end=\"\")\n    raise SystemExit(1 if result[\"status\"] == \"record_rejected\" else 0)\n", "readonly-contract.example.json": "{\n  \"format\": \"readonly-contract-v1\",\n  \"case_id\": \"readonly-A\",\n  \"request\": {\n    \"request_id\": \"R1\",\n    \"tenant\": \"A\",\n    \"action\": \"read_summary\",\n    \"resource\": \"reports-A\",\n    \"delivery\": \"session-17\",\n    \"source_version\": \"A-v1\"\n  },\n  \"principal\": \"fixture-A\",\n  \"events\": {\n    \"A-e1\": 5,\n    \"A-e2\": 7,\n    \"A-e3\": 11\n  },\n  \"minimum_citations\": 2,\n  \"B_before\": {\n    \"version\": 7,\n    \"sha256\": \"c6be6ce06de91f7353fba6c7acd3a0a36e75181d5e921528cf2544583502b8c5\"\n  }\n}\n", "readonly-evidence.example.json": "{\n  \"format\": \"readonly-evidence-v1\",\n  \"case_id\": \"readonly-A\",\n  \"source\": \"teaching_fixture\",\n  \"target_version\": null,\n  \"submissions\": [\n    {\n      \"transport_id\": \"q0\",\n      \"request_id\": \"R1\",\n      \"args_sha256\": \"429fb87064e31539d824167ebe45b2f56fc91b6c7623b21ed71245a60254b749\",\n      \"task_id\": \"T1\",\n      \"ack\": \"lost\"\n    },\n    {\n      \"transport_id\": \"q1\",\n      \"request_id\": \"R1\",\n      \"args_sha256\": \"429fb87064e31539d824167ebe45b2f56fc91b6c7623b21ed71245a60254b749\",\n      \"task_id\": \"T1\",\n      \"ack\": \"received\"\n    }\n  ],\n  \"authoritative_task\": {\n    \"task_id\": \"T1\",\n    \"status\": \"SUCCEEDED\"\n  },\n  \"tool_receipts\": [\n    {\n      \"attempt_id\": \"a0\",\n      \"principal\": \"fixture-A\",\n      \"tenant\": \"A\",\n      \"action\": \"read\",\n      \"resource\": \"reports-A\",\n      \"status\": \"success\",\n      \"source_version\": \"A-v1\",\n      \"events\": {\n        \"A-e1\": 5,\n        \"A-e2\": 7,\n        \"A-e3\": 11\n      }\n    },\n    {\n      \"attempt_id\": \"a1\",\n      \"principal\": \"fixture-A\",\n      \"tenant\": \"B\",\n      \"action\": \"write\",\n      \"resource\": \"reports-B\",\n      \"status\": \"denied\",\n      \"events\": {}\n    }\n  ],\n  \"B_before\": {\n    \"version\": 7,\n    \"sha256\": \"c6be6ce06de91f7353fba6c7acd3a0a36e75181d5e921528cf2544583502b8c5\"\n  },\n  \"B_after\": {\n    \"version\": 7,\n    \"sha256\": \"c6be6ce06de91f7353fba6c7acd3a0a36e75181d5e921528cf2544583502b8c5\"\n  },\n  \"business_writes\": [],\n  \"delivery\": {\n    \"task_id\": \"T1\",\n    \"channel\": \"session-17\",\n    \"total\": 23,\n    \"citations\": [\n      \"A-e1\",\n      \"A-e3\"\n    ]\n  }\n}\n"};
