const mechanismWalkthroughFiles={"route_walk.py": "\"\"\"CIDR and longest-prefix teaching model. Does not configure a real VPC.\"\"\"\nimport ipaddress\nimport json\n\n\ndef lookup(destination, routes):\n    address = ipaddress.ip_address(destination)\n    matches = [(ipaddress.ip_network(prefix), target) for prefix, target in routes\n               if address.version == ipaddress.ip_network(prefix).version\n               and address in ipaddress.ip_network(prefix)]\n    matches.sort(key=lambda row: row[0].prefixlen, reverse=True)\n    if not matches:\n        return None\n    # Equal-prefix source priorities are product-specific, outside this model.\n    if len(matches) > 1 and matches[0][0].prefixlen == matches[1][0].prefixlen:\n        raise ValueError('equal-prefix priority is not defined by this model')\n    return {'prefix': str(matches[0][0]), 'target': matches[0][1],\n            'matched': [str(net) for net, _ in matches]}\n\n\ndef main():\n    routes = [('10.20.0.0/16', 'local'), ('10.30.8.0/24', 'peer'),\n              ('0.0.0.0/0', 'nat')]\n    network = ipaddress.ip_network('10.30.8.0/24')\n    assert network.num_addresses == 256\n    assert ipaddress.ip_address('10.30.8.42') in network\n    assert ipaddress.ip_address('10.30.9.42') not in network\n    peer = lookup('10.30.8.42', routes)\n    assert peer['target'] == 'peer'\n    assert lookup('10.30.8.42', list(reversed(routes))) == peer\n    host = lookup('10.30.8.42', routes + [('10.30.8.42/32', 'inspection')])\n    assert host['target'] == 'inspection'\n    assert lookup('198.51.100.9', routes)['target'] == 'nat'\n    assert lookup('198.51.100.9', routes[:2]) is None\n    # A peer-side table needs its own return route to the client's subnet.\n    missing_return = lookup('10.20.4.7', [('10.30.8.0/24', 'local')])\n    fixed_return = lookup('10.20.4.7', [('10.30.8.0/24', 'local'),\n                                     ('10.20.0.0/16', 'peer-back')])\n    assert missing_return is None and fixed_return['target'] == 'peer-back'\n    try:\n        lookup('10.30.8.42', routes + [('10.30.8.0/24', 'other-peer')])\n    except ValueError:\n        equal_prefix_rejected = True\n    else:\n        raise AssertionError('ambiguous equal-prefix rule was silently accepted')\n    request = ['10.20.4.7', 51000, '10.30.8.42', 443, 'TCP']\n    response = [request[2], request[3], request[0], request[1], request[4]]\n    assert response[3] == 51000\n    print(json.dumps({'cidr': {'network': str(network), 'addresses': 256,\n                              'first': str(network[0]), 'last': str(network[-1])},\n                      'peer': peer, 'host_route': host,\n                      'missing_return': missing_return, 'fixed_return': fixed_return,\n                      'request_tuple': request, 'response_tuple': response,\n                      'equal_prefix_rejected': equal_prefix_rejected}, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n", "reconcile_walk.py": "\"\"\"Small in-memory reconciliation model, not Kubernetes API emulation.\"\"\"\nimport copy\nimport json\n\n\nclass Store:\n    def __init__(self):\n        self.revision = 0\n        self.next_uid = 0\n        self.object = {'uid': 'owner-A', 'generation': 1, 'spec': {'replicas': 2},\n                       'status': {'observedGeneration': 0, 'replicas': 0, 'readyReplicas': 0}}\n        self.pods = {}\n        self.bump()\n\n    def bump(self):\n        self.revision += 1\n        # Readers compare this token for equality; never parse it as a number.\n        self.object['resourceVersion'] = 'opaque-' + str(self.revision)\n\n    def read(self):\n        return copy.deepcopy(self.object)\n\n    def set_replicas(self, expected_version, replicas):\n        if expected_version != self.object['resourceVersion']:\n            return 'conflict'\n        if replicas != self.object['spec']['replicas']:\n            self.object['spec']['replicas'] = replicas\n            self.object['generation'] += 1\n            self.bump()\n        return 'accepted'\n\n    def create(self, name):\n        if name in self.pods:\n            return self.pods[name]\n        self.next_uid += 1\n        pod = {'name': name, 'uid': 'pod-' + str(self.next_uid),\n               'owner': self.object['uid'], 'ready': False}\n        self.pods[name] = pod\n        return pod\n\n    def sync(self):\n        desired = self.read()\n        owned = [p for p in self.pods.values() if p['owner'] == desired['uid']]\n        if len(owned) < desired['spec']['replicas']:\n            name = next('p'+str(i) for i in range(100) if 'p'+str(i) not in self.pods)\n            self.create(name)\n        elif len(owned) > desired['spec']['replicas']:\n            del self.pods[owned[-1]['name']]\n        actual = [p for p in self.pods.values() if p['owner'] == desired['uid']]\n        status = {'observedGeneration': desired['generation'], 'replicas': len(actual),\n                  'readyReplicas': sum(p['ready'] for p in actual)}\n        if status != self.object['status']:\n            self.object['status'] = status\n            self.bump()\n\n    def delete_pod(self, name, expected_uid):\n        if name not in self.pods or self.pods[name]['uid'] != expected_uid:\n            return 'uid-mismatch'\n        del self.pods[name]\n        return 'deleted'\n\n\ndef main():\n    s = Store()\n    old = s.read()\n    assert s.set_replicas(old['resourceVersion'], 3) == 'accepted'\n    accepted = s.read()\n    assert (accepted['generation'], accepted['status']['observedGeneration']) == (2, 0)\n    assert not s.pods\n    assert s.set_replicas(old['resourceVersion'], 1) == 'conflict'\n    for _ in range(8):  # Duplicate wake-ups still converge to three, not eight.\n        s.sync()\n    converged = s.read()\n    assert len(s.pods) == 3 and converged['status'] == {'observedGeneration': 2, 'replicas': 3, 'readyReplicas': 0}\n    s.sync()\n    assert s.read() == converged  # No change needed; avoid a needless status write.\n    old_uid = s.pods['p0']['uid']\n    assert s.delete_pod('p0', old_uid) == 'deleted'\n    s.sync()\n    new_uid = s.pods['p0']['uid']\n    assert new_uid != old_uid\n    assert s.delete_pod('p0', old_uid) == 'uid-mismatch'\n    for pod in s.pods.values():\n        pod['ready'] = True\n    s.sync()\n    ready = s.read()\n    assert ready['generation'] == 2 and ready['status']['readyReplicas'] == 3\n    assert ready['resourceVersion'] != converged['resourceVersion']\n    assert s.set_replicas(ready['resourceVersion'], 1) == 'accepted'\n    for _ in range(3):\n        s.sync()\n    assert len(s.pods) == 1\n    print(json.dumps({'accepted': accepted, 'converged': converged,\n                      'replacement': {'old_uid': old_uid, 'new_uid': new_uid,\n                                      'stale_delete': 'uid-mismatch'},\n                      'ready': ready, 'scaled_down': s.read(),\n                      'stale_update': 'conflict', 'noop_keeps_version': True}, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n", "attention_trace.py": "\"\"\"Actual PyTorch CPU trace for the chapter's three-position attention example.\"\"\"\nimport json\nimport math\nimport torch\nfrom torch.nn import functional as F\n\n\ndef reference(q, k, v, allowed):\n    if not bool(allowed.any(dim=-1).all()):\n        raise ValueError('this reference requires at least one allowed key per query')\n    scores = q @ k.T / math.sqrt(q.shape[-1])\n    weights = scores.masked_fill(~allowed, -torch.inf).softmax(dim=-1)\n    return scores, weights, weights @ v\n\n\ndef main():\n    torch.set_num_threads(1)\n    q = torch.tensor([[0., 0.], [math.sqrt(2), 0.], [0., math.sqrt(2)]], dtype=torch.float64)\n    k = torch.tensor([[0., 0.], [math.log(3), 0.], [0., math.log(2)]], dtype=torch.float64)\n    v = torch.tensor([[2., 0.], [0., 4.], [6., 2.]], dtype=torch.float64)\n    causal = torch.ones(3, 3, dtype=torch.bool).tril()\n    scores, weights, out = reference(q, k, v, causal)\n    expected_weights = torch.tensor([[1, 0, 0], [.25, .75, 0], [.25, .25, .5]], dtype=q.dtype)\n    expected_out = torch.tensor([[2, 0], [.5, 3], [3.5, 2]], dtype=q.dtype)\n    torch.testing.assert_close(weights, expected_weights, atol=1e-12, rtol=1e-12)\n    torch.testing.assert_close(out, expected_out, atol=1e-12, rtol=1e-12)\n    actual = F.scaled_dot_product_attention(q, k, v, attn_mask=causal, dropout_p=0.0)\n    torch.testing.assert_close(actual, expected_out, atol=1e-12, rtol=1e-12)\n    changed = v.clone(); changed[2, 0] = 60\n    changed_out = reference(q, k, changed, causal)[2]\n    torch.testing.assert_close(changed_out[:2], out[:2])\n    assert abs(changed_out[2, 0].item() - 30.5) < 1e-12\n    # Multiplication by zero leaves forbidden positions in the softmax denominator.\n    zero_mask_out = (scores * causal).softmax(-1) @ v\n    torch.testing.assert_close(zero_mask_out[1], torch.tensor([1.6, 2.8], dtype=q.dtype))\n    valid_keys = torch.tensor([True, False, True])\n    padded = reference(q, k, v, causal & valid_keys[None, :])[2]\n    torch.testing.assert_close(padded[2], torch.tensor([14/3, 4/3], dtype=q.dtype))\n    # A new query at absolute position 2 may read all three stored keys.\n    cached = F.scaled_dot_product_attention(q[2:], k, v, dropout_p=0.0)\n    wrong_offset = F.scaled_dot_product_attention(q[2:], k, v, is_causal=True, dropout_p=0.0)\n    torch.testing.assert_close(cached[0], out[2])\n    torch.testing.assert_close(wrong_offset[0], v[0])\n    explicit = torch.arange(3)[None, :] <= torch.tensor([1, 2])[:, None]\n    chunked = F.scaled_dot_product_attention(q[1:], k, v, attn_mask=explicit, dropout_p=0.0)\n    torch.testing.assert_close(chunked, out[1:])\n    # The main fixture's scores are symmetric; a separate asymmetric fixture is essential.\n    asymmetric_k = k.clone(); asymmetric_k[0] = torch.tensor([.7, -.2], dtype=q.dtype)\n    good_asym = reference(q, asymmetric_k, v, causal)[2]\n    swapped_asym = reference(asymmetric_k, q, v, causal)[2]\n    asym_error = (good_asym - swapped_asym).abs().max().item()\n    assert asym_error > .1\n    packed = torch.tensor([[[0, 1, 2, 3], [10, 11, 12, 13]]])\n    heads = packed.reshape(1, 2, 2, 2).transpose(1, 2)\n    wrong_heads = packed.reshape(1, 2, 2, 2)\n    assert heads[0, 0].tolist() == [[0, 1], [10, 11]]\n    assert wrong_heads[0, 0].tolist() == [[0, 1], [2, 3]]\n    torch.testing.assert_close(heads.transpose(1, 2).reshape(1, 2, 4), packed)\n    empty = causal.clone(); empty[0] = False\n    try:\n        reference(q, k, v, empty)\n    except ValueError:\n        empty_rejected = True\n    else:\n        raise AssertionError('undefined all-masked row accepted')\n    print(json.dumps({'torch': str(torch.__version__), 'device': 'cpu', 'dtype': str(q.dtype),\n                      'scaled_scores': scores.tolist(), 'weights': weights.tolist(),\n                      'output': out.tolist(), 'sdpa_max_error': (actual-out).abs().max().item(),\n                      'future_changed_output': changed_out.tolist(),\n                      'zero_mask_row_1': zero_mask_out[1].tolist(),\n                      'padding_last_row': padded[2].tolist(),\n                      'cached_last_row': cached[0].tolist(), 'wrong_offset_row': wrong_offset[0].tolist(),\n                      'chunk_max_error': (chunked-out[1:]).abs().max().item(),\n                      'asymmetric_transpose_error': asym_error,\n                      'head_0_correct': heads[0, 0].tolist(), 'head_0_wrong': wrong_heads[0, 0].tolist(),\n                      'empty_row_rejected': empty_rejected}, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n", "decoder_trace.py": "\"\"\"Inspect a real CPU decoder forward pass and four shape-compatible wiring faults.\"\"\"\nimport copy\nimport json\nimport math\nimport torch\nfrom torch.nn import functional as F\nfrom tiny_decoder import TinyDecoder\n\n\ndef trace(model, ids, fault=None):\n    batch, length = ids.shape\n    x = model.token(ids) + model.position(torch.arange(length))\n    if fault == 'normalize_time':\n        n1 = x / (x.square().mean(dim=1, keepdim=True) + 1e-6).sqrt() * model.norm1.weight\n    else:\n        n1 = model.norm1(x)\n    q, k, v = (a.reshape(batch, length, 2, 4).transpose(1, 2)\n               for a in model.qkv(n1).chunk(3, dim=-1))\n    z = F.scaled_dot_product_attention(q, k, v, is_causal=True, dropout_p=0.0)\n    attn = model.out(z.transpose(1, 2).reshape(batch, length, 8))\n    h1 = x + attn\n    n2 = model.norm2(x if fault == 'stale_input' else h1)\n    gate, up = model.gate(n2), model.up(n2)\n    product = F.silu(up) * gate if fault == 'swap_gate' else F.silu(gate) * up\n    ffn = model.down(product)\n    h2 = ffn if fault == 'skip_residual' else h1 + ffn\n    logits = F.linear(model.norm_out(h2), model.token.weight)\n    return {'x': x, 'n1': n1, 'attn': attn, 'h1': h1, 'n2': n2,\n            'gate_product': product, 'ffn': ffn, 'h2': h2, 'logits': logits}\n\n\ndef first_difference(left, right):\n    return next((key for key in left if not torch.allclose(left[key], right[key],\n                                                         atol=1e-12, rtol=1e-12)), None)\n\n\ndef main():\n    torch.manual_seed(7)\n    torch.set_num_threads(1)\n    model = TinyDecoder().double()\n    ids = torch.tensor([[0, 1, 2, 3], [4, 5, 6, 7]])\n    with torch.no_grad():\n        good = trace(model, ids)\n        torch.testing.assert_close(good['logits'], model(ids), atol=1e-12, rtol=1e-12)\n        expected = {'stale_input': 'n2', 'swap_gate': 'gate_product',\n                    'skip_residual': 'h2', 'normalize_time': 'n1'}\n        faults = {}\n        for fault, first in expected.items():\n            bad = trace(model, ids, fault)\n            actual_first = first_difference(good, bad)\n            assert actual_first == first\n            faults[fault] = {'first_difference': first,\n                             'logit_max_difference': (good['logits']-bad['logits']).abs().max().item()}\n        future = ids.clone(); future[:, 3] = (future[:, 3] + 1) % 8\n        correct_prefix_error = (trace(model, future)['logits'][:, :3]-good['logits'][:, :3]).abs().max().item()\n        wrong_prefix_error = (trace(model, future, 'normalize_time')['logits'][:, :3]\n                              - trace(model, ids, 'normalize_time')['logits'][:, :3]).abs().max().item()\n        assert correct_prefix_error < 1e-12 and wrong_prefix_error > 1e-4\n        zero = copy.deepcopy(model)\n        zero.out.weight.zero_(); zero.down.weight.zero_()\n        zero_good = trace(zero, ids)\n        torch.testing.assert_close(zero_good['h2'], zero_good['x'])\n        assert trace(zero, ids, 'skip_residual')['h2'].count_nonzero().item() == 0\n        x = torch.tensor([[1., 3.], [3., 5.]], dtype=torch.float64)\n        layer = F.layer_norm(x, (2,), eps=1e-6)\n        rms = F.rms_norm(x, (2,), eps=1e-6)\n        expected_layer = torch.tensor([[-1., 1.], [-1., 1.]], dtype=x.dtype) / (1+1e-6)**.5\n        expected_rms = torch.tensor([[1/(5+1e-6)**.5, 3/(5+1e-6)**.5],\n                                     [3/(17+1e-6)**.5, 5/(17+1e-6)**.5]], dtype=x.dtype)\n        torch.testing.assert_close(layer, expected_layer, atol=1e-12, rtol=1e-12)\n        torch.testing.assert_close(rms, expected_rms, atol=1e-12, rtol=1e-12)\n        gate = torch.tensor([0., math.log(3)], dtype=torch.float64)\n        up = torch.tensor([5., 2.], dtype=torch.float64)\n        down = torch.tensor([[1., -1.], [2., 1.]], dtype=torch.float64)\n        hand_gate_output = (F.silu(gate) * up) @ down\n        torch.testing.assert_close(hand_gate_output, torch.tensor([3*math.log(3), 1.5*math.log(3)], dtype=torch.float64))\n    scalar = torch.tensor(2., requires_grad=True)\n    (scalar + .5*scalar).backward()\n    assert scalar.grad.item() == 1.5\n    print(json.dumps({'torch': str(torch.__version__), 'device': 'cpu', 'parameters': sum(p.numel() for p in model.parameters()),\n                      'shapes': {key: list(value.shape) for key, value in good.items()},\n                      'first_position': {key: value[0, 0].tolist() for key, value in good.items()},\n                      'forward_max_error': (good['logits']-model(ids)).abs().max().item(),\n                      'faults': faults, 'future_prefix_error': correct_prefix_error,\n                      'time_normalized_future_prefix_error': wrong_prefix_error,\n                      'zero_branches_keep_input': True, 'layer_norm': layer.tolist(),\n                      'rms_norm': rms.tolist(), 'swiglu_hand_output': hand_gate_output.tolist(),\n                      'residual_scalar_gradient': scalar.grad.item()}, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n", "tiny_decoder.py": "\"\"\"One CPU update of a miniature next-token model; no downloads required.\"\"\"\nimport copy\nimport json\n\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\n\n\nclass TinyDecoder(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.token = nn.Embedding(8, 8)\n        self.position = nn.Embedding(4, 8)\n        self.norm1 = nn.RMSNorm(8, eps=1e-6)\n        self.norm2 = nn.RMSNorm(8, eps=1e-6)\n        self.norm_out = nn.RMSNorm(8, eps=1e-6)\n        self.qkv = nn.Linear(8, 24, bias=False)\n        self.out = nn.Linear(8, 8, bias=False)\n        self.gate = nn.Linear(8, 12, bias=False)\n        self.up = nn.Linear(8, 12, bias=False)\n        self.down = nn.Linear(12, 8, bias=False)\n\n    def forward(self, ids):\n        batch, length = ids.shape\n        pos = torch.arange(length, device=ids.device)\n        x = self.token(ids) + self.position(pos)\n        # [B,T,3D] -> three [B,H,T,d] views\n        q, k, v = (t.reshape(batch, length, 2, 4).transpose(1, 2)\n                   for t in self.qkv(self.norm1(x)).chunk(3, dim=-1))\n        z = F.scaled_dot_product_attention(q, k, v, is_causal=True, dropout_p=0.0)\n        joined = z.transpose(1, 2).reshape(batch, length, 8)\n        x = x + self.out(joined)\n        u = self.norm2(x)\n        x = x + self.down(F.silu(self.gate(u)) * self.up(u))\n        return F.linear(self.norm_out(x), self.token.weight)\n\n\ndef loss_sum(logits, labels):\n    return F.cross_entropy(logits.reshape(-1, 8), labels.reshape(-1),\n                           ignore_index=-100, reduction=\"sum\")\n\n\ndef update(model, x, labels, micro_size):\n    optimizer = torch.optim.SGD(model.parameters(), lr=0.05)\n    optimizer.zero_grad(set_to_none=True)\n    valid = int((labels != -100).sum())\n    if valid == 0:\n        return None\n    total_loss = 0.0\n    for start in range(0, len(x), micro_size):\n        sl = slice(start, start + micro_size)\n        subtotal = loss_sum(model(x[sl]), labels[sl])\n        (subtotal / valid).backward()\n        total_loss += subtotal.detach().item()\n    optimizer.step()\n    return total_loss / valid\n\n\ndef main():\n    torch.manual_seed(7)\n    torch.set_num_threads(1)\n    base = TinyDecoder().double()\n    assert sum(p.numel() for p in base.parameters()) == 664\n    rows = torch.tensor([[0, 1, 2, 3, 4], [4, 5, 6, 7, 0]])\n    x, labels = rows[:, :-1], rows[:, 1:].clone()\n    labels[0, 1:] = -100\n    labels[1, 3:] = -100\n    assert (labels != -100).sum(dim=1).tolist() == [1, 3]\n\n    with torch.no_grad():\n        logits = base(x)\n        changed = x.clone()\n        changed[:, 3] = (changed[:, 3] + 1) % 8\n        torch.testing.assert_close(base(changed)[:, :3], logits[:, :3])\n        assert logits.shape == (2, 4, 8) and logits.isfinite().all()\n\n    full, micro = copy.deepcopy(base), copy.deepcopy(base)\n    full_loss = update(full, x, labels, micro_size=2)\n    micro_loss = update(micro, x, labels, micro_size=1)\n    assert abs(full_loss - micro_loss) < 1e-12\n    largest_diff = 0.0\n    for a, b in zip(full.parameters(), micro.parameters()):\n        torch.testing.assert_close(a.grad, b.grad, atol=1e-10, rtol=1e-10)\n        torch.testing.assert_close(a, b, atol=1e-10, rtol=1e-10)\n        largest_diff = max(largest_diff, (a.grad - b.grad).abs().max().item())\n    assert not torch.equal(full.token.weight, base.token.weight)\n    empty = copy.deepcopy(base)\n    assert update(empty, x, torch.full_like(labels, -100), micro_size=1) is None\n    for a, b in zip(base.parameters(), empty.parameters()):\n        assert torch.equal(a, b)\n    with torch.no_grad():\n        after_loss = loss_sum(full(x), labels).item() / 4\n    print(json.dumps({\"torch\": str(torch.__version__), \"device\": \"cpu\",\n                      \"parameters\": 664, \"valid_targets\": [1, 3],\n                      \"loss_before\": full_loss, \"loss_after\": after_loss,\n                      \"max_grad_diff\": largest_diff}, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "workflow_history.py": "\"\"\"Local durable-history exercise with real process exits, not a Temporal SDK clone.\n\nThe interpreter matches activity id/name/order. Its rules are explicitly local.\nActivities only read a fixture and render text. No model or remote write is called.\n\"\"\"\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport sqlite3\nimport subprocess\nimport sys\nimport tempfile\n\n\nclass ReplayMismatch(Exception):\n    pass\n\n\nclass Runner:\n    def __init__(self, database, source, stop='none'):\n        self.db = sqlite3.connect(database)\n        self.db.execute('CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY, kind TEXT, payload TEXT)')\n        self.audit = sqlite3.connect(str(database)+'.calls')\n        self.audit.execute('CREATE TABLE IF NOT EXISTS calls(name TEXT)')\n        self.source, self.stop, self.cursor = source, stop, 0\n        if not self.events():\n            self.append('started', {'definition_version': 1})\n\n    def events(self):\n        return [(seq, kind, json.loads(payload)) for seq, kind, payload\n                in self.db.execute('SELECT seq,kind,payload FROM events ORDER BY seq')]\n\n    def append(self, kind, payload):\n        self.db.execute('INSERT INTO events(kind,payload) VALUES(?,?)',\n                        (kind, json.dumps(payload, ensure_ascii=False)))\n        self.db.commit()\n\n    def activity(self, ident, name, args):\n        history = self.events()\n        commands = [p for _, k, p in history if k == 'scheduled']\n        finished = any(k == 'finished' for _, k, _ in history)\n        if self.cursor < len(commands):\n            saved = commands[self.cursor]\n            if (saved['id'], saved['name']) != (ident, name):\n                raise ReplayMismatch('activity id/name/order differs from recorded command')\n        else:\n            if finished:\n                raise ReplayMismatch('new command after a completed history')\n            saved = {'id': ident, 'name': name, 'args': args}\n            self.append('scheduled', saved)\n        self.cursor += 1\n        completed = [p for _, kind, p in history if kind == 'completed' and p['id'] == ident]\n        if completed:\n            return completed[0]['result']\n        # This separate audit counts calls even if result recording later fails.\n        self.audit.execute('INSERT INTO calls VALUES(?)', (name,)); self.audit.commit()\n        if name == 'read_metrics':\n            result = json.loads(Path(self.source).read_text(encoding='utf-8'))\n        elif name == 'render_draft':\n            result = 'A日报：总数'+str(saved['args']['total'])\n        else:\n            raise ValueError('unknown local activity')\n        if self.stop == 'read-result' and name == 'read_metrics':\n            os._exit(24)  # Call happened, but COMPLETED is not committed.\n        self.append('completed', {'id': ident, 'result': result})\n        if self.stop == 'read-completed' and name == 'read_metrics':\n            os._exit(23)  # Recorded result survives this process exit.\n        return result\n\n    def run(self, incompatible=False, extra=False):\n        result = self.activity('read-1', 'render_draft' if incompatible else 'read_metrics', {})\n        draft = self.activity('draft-1', 'render_draft', {'total': result['total']})\n        if extra:\n            self.activity('draft-extra', 'render_draft', {'total': 0})\n        commands = [p for _, kind, p in self.events() if kind == 'scheduled']\n        if self.cursor != len(commands):\n            raise ReplayMismatch('recorded commands were omitted by new code')\n        if not any(kind == 'finished' for _, kind, _ in self.events()):\n            self.append('finished', {'draft': draft})\n        return draft\n\n\ndef observe(database):\n    with sqlite3.connect(database) as db:\n        events = [{'seq': seq, 'kind': kind, 'payload': json.loads(p)}\n                  for seq, kind, p in db.execute('SELECT seq,kind,payload FROM events ORDER BY seq')]\n    with sqlite3.connect(str(database)+'.calls') as db:\n        calls = [name for (name,) in db.execute('SELECT name FROM calls')]\n    return {'events': events, 'calls': calls}\n\n\ndef child(database, source, *flags):\n    return subprocess.run([sys.executable, str(Path(__file__).resolve()), '--worker',\n                           str(database), str(source), *flags], capture_output=True, text=True)\n\n\ndef main():\n    with tempfile.TemporaryDirectory() as directory:\n        directory = Path(directory)\n        source, db = directory/'metrics.json', directory/'history.sqlite3'\n        source.write_text('{\"version\":\"v1\",\"total\":23}', encoding='utf-8')\n        crashed = child(db, source, '--stop', 'read-completed')\n        assert crashed.returncode == 23\n        after_crash = observe(db)\n        assert [e['kind'] for e in after_crash['events']] == ['started', 'scheduled', 'completed']\n        source.write_text('{\"version\":\"v2\",\"total\":999}', encoding='utf-8')\n        resumed = child(db, source); assert resumed.returncode == 0, resumed.stderr\n        assert json.loads(resumed.stdout)['draft'] == 'A日报：总数23'\n        after_resume = observe(db)\n        assert after_resume['calls'] == ['read_metrics', 'render_draft']\n        replay = child(db, source); assert replay.returncode == 0, replay.stderr\n        assert observe(db) == after_resume\n        incompatible = child(db, source, '--incompatible')\n        extra = child(db, source, '--extra')\n        assert incompatible.returncode == extra.returncode == 4\n        assert observe(db) == after_resume\n        gap_db = directory/'gap.sqlite3'\n        source.write_text('{\"version\":\"v1\",\"total\":23}', encoding='utf-8')\n        gap_crash = child(gap_db, source, '--stop', 'read-result')\n        assert gap_crash.returncode == 24\n        before_gap_resume = observe(gap_db)\n        assert len(before_gap_resume['events']) == 2 and before_gap_resume['calls'] == ['read_metrics']\n        source.write_text('{\"version\":\"v2\",\"total\":999}', encoding='utf-8')\n        gap_resume = child(gap_db, source); assert gap_resume.returncode == 0, gap_resume.stderr\n        assert json.loads(gap_resume.stdout)['draft'] == 'A日报：总数999'\n        gap = observe(gap_db)\n        assert gap['calls'] == ['read_metrics', 'read_metrics', 'render_draft']\n        print(json.dumps({'scope': 'local interpreter; no Temporal/LLM/remote side effect',\n                          'recorded_result_exit_code': crashed.returncode, 'after_crash': after_crash,\n                          'after_resume': after_resume, 'replay_added_events': 0, 'replay_added_calls': 0,\n                          'incompatible_code_exit': incompatible.returncode, 'extra_command_exit': extra.returncode,\n                          'unrecorded_result_exit_code': gap_crash.returncode,\n                          'before_gap_resume': before_gap_resume, 'after_gap_resume': gap}, ensure_ascii=False, indent=2))\n\n\nif __name__ == '__main__':\n    parser = argparse.ArgumentParser()\n    parser.add_argument('--worker', nargs=2)\n    parser.add_argument('--stop', choices=['none', 'read-result', 'read-completed'], default='none')\n    parser.add_argument('--incompatible', action='store_true')\n    parser.add_argument('--extra', action='store_true')\n    args = parser.parse_args()\n    if args.worker:\n        try:\n            runner = Runner(Path(args.worker[0]), Path(args.worker[1]), args.stop)\n            print(json.dumps({'draft': runner.run(args.incompatible, args.extra)}, ensure_ascii=False))\n        except ReplayMismatch as error:\n            print(json.dumps({'error': str(error)})); sys.exit(4)\n    else:\n        main()\n"};
