const transportRecoveryFiles={"epoll_ready.py": "\"\"\"Observe real Linux epoll readiness; no simulation or throughput benchmark.\"\"\"\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport select\nimport socket\nimport sys\n\n\ndef pipe_case(edge):\n    reader, writer = os.pipe()\n    os.set_blocking(reader, False)\n    os.set_blocking(writer, False)\n    try:\n        with select.epoll() as poller:\n            poller.register(reader, select.EPOLLIN | (select.EPOLLET if edge else 0))\n            os.write(writer, b'abcdef')\n            first = poller.poll(1)\n            assert len(first) == 1 and first[0][1] & select.EPOLLIN\n            prefix = os.read(reader, 2)\n            second = poller.poll(0)\n            # No new write has occurred. Four unread bytes are still in the pipe.\n            assert bool(second) == (not edge)\n            suffix = os.read(reader, 64)\n            assert prefix == b'ab' and suffix == b'cdef'\n            try:\n                os.read(reader, 64)\n            except BlockingIOError:\n                eagain = True\n            else:\n                raise AssertionError('empty, open pipe must report EAGAIN')\n            os.write(writer, b'gh')\n            third = poller.poll(1)\n            assert third and third[0][1] & select.EPOLLIN\n            after_write = os.read(reader, 64)\n            os.close(writer)\n            writer = None\n            hangup = poller.poll(1)\n            eof = os.read(reader, 64)\n            assert hangup and hangup[0][1] & select.EPOLLHUP and eof == b''\n            return {'mode': 'ET' if edge else 'LT', 'first_notification': True,\n                    'first_read': prefix.decode(), 'notification_without_new_write': bool(second),\n                    'unread_then_drained': suffix.decode(), 'eagain_after_drain': eagain,\n                    'new_write_notifies': after_write.decode(), 'eof_after_writer_close': True}\n    finally:\n        os.close(reader)\n        if writer is not None:\n            os.close(writer)\n\n\ndef application_ready_queue():\n    reader, writer = os.pipe()\n    os.set_blocking(reader, False)\n    try:\n        with select.epoll() as poller:\n            poller.register(reader, select.EPOLLIN | select.EPOLLET)\n            os.write(writer, b'abcdef')\n            assert poller.poll(1)\n            # Retain application ownership until EAGAIN. Each turn reads at most two bytes.\n            ready = [reader]\n            turns = []\n            while ready:\n                fd = ready.pop(0)\n                try:\n                    chunk = os.read(fd, 2)\n                except BlockingIOError:\n                    turns.append('EAGAIN')\n                    continue\n                assert chunk\n                turns.append(chunk.decode())\n                ready.append(fd)\n                assert poller.poll(0) == [], 'there was no new write/edge'\n            assert turns == ['ab', 'cd', 'ef', 'EAGAIN']\n            return {'kernel_notifications': 1, 'application_turns': turns,\n                    'payload': ''.join(turns[:-1]), 'per_turn_read_budget': 2}\n    finally:\n        os.close(reader)\n        os.close(writer)\n\n\ndef writable_interest():\n    left, right = socket.socketpair()\n    left.setblocking(False)\n    try:\n        with select.epoll() as poller:\n            poller.register(left, select.EPOLLIN | select.EPOLLOUT)\n            seen = [any(mask & select.EPOLLOUT for _, mask in poller.poll(0)) for _ in range(3)]\n            assert seen == [True, True, True]\n            poller.modify(left, select.EPOLLIN)\n            assert poller.poll(0) == []\n            return {'no_output_queued': True, 'write_notifications_in_three_polls': sum(seen),\n                    'notifications_after_removing_write_interest': 0}\n    finally:\n        left.close()\n        right.close()\n\n\ndef main():\n    result = {'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n              'python': platform.python_version(), 'system': platform.system(),\n              'scope': 'Actual local pipe/socket epoll calls; no TCP packet trace, load test or cloud network.'}\n    if not hasattr(select, 'epoll'):\n        result.update(status='unsupported', reason='select.epoll requires Linux')\n    else:\n        result.update(status='passed', cases={'lt': pipe_case(False), 'et': pipe_case(True),\n                      'application_queue': application_ready_queue(), 'writable_interest': writable_interest()})\n    print(json.dumps(result, ensure_ascii=False, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n", "mysql_restore.py": "\"\"\"Isolated MySQL 8.4 crash/PITR lesson using Docker and synthetic balances only.\n\nCreates uniquely named containers and volumes, exposes no ports, removes only\nits own resources, and never connects to an existing MySQL server.\n\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport re\nimport secrets\nimport selectors\nimport subprocess\nimport tempfile\nimport time\nimport uuid\n\n\nclass Lab:\n    def __init__(self, image, folder):\n        self.image, self.folder = image, folder\n        self.prefix = 'infra-pitr-' + uuid.uuid4().hex[:12]\n        self.containers, self.volumes = [], []\n        self.data_volumes = {}\n        self.tools_image = 'infra-pitr-tools:' + self.prefix\n        self.password = secrets.token_urlsafe(28)\n        self.config = folder / 'client.cnf'\n        self.config.write_text('[client]\\nuser=root\\npassword=' + self.password + '\\nprotocol=socket\\n')\n        self.config.chmod(0o600)\n\n    def docker(self, *args, data=None, check=True, timeout=90, env=None):\n        result = subprocess.run(['docker', *args], input=data, capture_output=True,\n                                timeout=timeout, env=env)\n        if check and result.returncode:\n            detail = (result.stderr or result.stdout).decode(errors='replace').replace(self.password, '[redacted]')\n            raise RuntimeError('Docker ' + args[0] + ' exited ' + str(result.returncode) + ': ' + detail[-1800:])\n        return result\n\n    def start(self, role, server_id, binary_log):\n        name, volume = self.prefix + '-' + role, self.prefix + '-' + role + '-data'\n        self.docker('volume', 'create', '--label', 'infraguide=isolated-lesson', volume)\n        self.volumes.append(volume)\n        self.data_volumes[name] = volume\n        env = dict(os.environ, MYSQL_ROOT_PASSWORD=self.password)\n        args = ['run', '-d', '--name', name, '--network', 'none', '--memory', '1g',\n                '--pids-limit', '256', '--env', 'MYSQL_ROOT_PASSWORD',\n                '--mount', 'type=volume,source=' + volume + ',target=/var/lib/mysql',\n                '--mount', 'type=bind,source=' + str(self.config) + ',target=/run/infra-client.cnf,readonly',\n                self.image, '--server-id=' + str(server_id), '--skip-networking',\n                '--innodb-buffer-pool-size=67108864', '--innodb-redo-log-capacity=67108864',\n                '--innodb-flush-log-at-trx-commit=1', '--sync-binlog=1', '--gtid-mode=OFF',\n                '--binlog-format=ROW', '--binlog-expire-logs-seconds=0',\n                '--log-bin=mysql-bin' if binary_log else '--skip-log-bin']\n        self.containers.append(name)\n        self.docker(*args, env=env)\n        self.wait(name)\n        return name\n\n    def mysql_args(self, name):\n        return ['docker', 'exec', '-i', name, 'mysql', '--defaults-extra-file=/run/infra-client.cnf',\n                '--batch', '--raw', '--skip-column-names', '--binary-mode', '--unbuffered']\n\n    def sql(self, name, sql, check=True):\n        data = sql.encode() if isinstance(sql, str) else sql\n        result = subprocess.run(self.mysql_args(name), input=data, capture_output=True, timeout=45)\n        if check and result.returncode:\n            raise RuntimeError(result.stderr.decode(errors='replace').replace(self.password, '[redacted]')[:1800])\n        return result\n\n    def wait(self, name):\n        deadline = time.monotonic() + 180\n        while time.monotonic() < deadline:\n            attempt = self.sql(name, 'SELECT 1;', check=False)\n            if attempt.returncode == 0 and attempt.stdout.strip() == b'1':\n                return\n            time.sleep(1)\n        raise RuntimeError('MySQL readiness timeout for the isolated lesson container')\n\n    def position(self, name):\n        row = self.sql(name, 'SHOW BINARY LOG STATUS;').stdout.decode().splitlines()[0].split('\\t')\n        return {'file': row[0], 'position': int(row[1])}\n\n    def commit(self, name, op, delta=None, reset=False):\n        mutation = 'UPDATE lab.account SET balance=0 WHERE id=1;' if reset else (\n            'UPDATE lab.account SET balance=balance+(' + str(delta) + ') WHERE id=1;')\n        amount = -125 if reset else delta\n        self.sql(name, \"START TRANSACTION;\" + mutation +\n                 \"INSERT INTO lab.receipt VALUES ('\" + op + \"',\" + str(amount) + \");COMMIT;\")\n\n    def state(self, name):\n        balance = int(self.sql(name, 'SELECT balance FROM lab.account WHERE id=1;').stdout.strip())\n        rows = self.sql(name, 'SELECT op_id,delta FROM lab.receipt ORDER BY op_id;').stdout.decode().splitlines()\n        return {'balance': balance, 'operations': [[a, int(b)] for a, b in (r.split('\\t') for r in rows)]}\n\n    def restore(self, target, baseline, stream=b''):\n        self.sql(target, 'DROP DATABASE IF EXISTS lab;')\n        self.sql(target, baseline)\n        if stream:\n            self.sql(target, stream)\n        return self.state(target)\n\n    def binlog(self, source, files, start, stop=None):\n        args = ['run', '--rm', '--network', 'none', '--mount',\n                'type=volume,source=' + self.data_volumes[source] + ',target=/var/lib/mysql,readonly',\n                self.tools_image, '--start-position=' + str(start)]\n        if stop is not None:\n            args.append('--stop-position=' + str(stop))\n        args.extend('/var/lib/mysql/' + f for f in files)\n        return self.docker(*args).stdout\n\n    def cleanup(self):\n        for name in reversed(self.containers):\n            self.docker('rm', '-f', name, check=False)\n        for volume in reversed(self.volumes):\n            self.docker('volume', 'rm', volume, check=False)\n        self.docker('image', 'rm', self.tools_image, check=False)\n\n    def run(self):\n        self.docker('pull', self.image, timeout=300)\n        digest = json.loads(self.docker('image', 'inspect', self.image, '--format', '{{json .RepoDigests}}').stdout)\n        tool_file = Path(__file__).with_name('Dockerfile.tools')\n        self.docker('build', '--quiet', '--tag', self.tools_image, '--build-arg',\n                    'MYSQL_BASE=' + self.image, '--file', str(tool_file), str(tool_file.parent), timeout=360)\n        binlog_version = self.docker('run', '--rm', '--network', 'none', self.tools_image, '--version').stdout.decode().strip()\n        assert re.search(r'Ver\\s+8\\.4\\.', binlog_version), 'Use the MySQL 8.4 client toolchain'\n        source = self.start('source', 101, True)\n        version = self.sql(source, 'SELECT VERSION();').stdout.decode().strip()\n        assert version.startswith('8.4.'), 'This lesson is explicitly scoped to MySQL 8.4'\n        self.sql(source, 'CREATE DATABASE lab;CREATE TABLE lab.account(id INT PRIMARY KEY,balance BIGINT NOT NULL) ENGINE=InnoDB;'\n                 'CREATE TABLE lab.receipt(op_id VARCHAR(32) PRIMARY KEY,delta BIGINT NOT NULL) ENGINE=InnoDB;'\n                 'INSERT INTO lab.account VALUES(1,100);')\n        baseline = self.docker('exec', source, 'mysqldump', '--defaults-extra-file=/run/infra-client.cnf',\n                              '--single-transaction', '--source-data=2', '--set-gtid-purged=OFF',\n                              '--databases', 'lab').stdout\n        match = re.search(rb\"SOURCE_LOG_FILE='([^']+)', SOURCE_LOG_POS=(\\d+)\", baseline)\n        assert match, 'The consistent snapshot must include its actual source coordinates'\n        start = {'file': match[1].decode(), 'position': int(match[2])}\n        self.commit(source, 'T101', 10)\n        self.sql(source, 'FLUSH BINARY LOGS;')\n        self.commit(source, 'T102', 20)\n        self.commit(source, 'T103', -5)\n        stop = self.position(source)\n        before_bad = self.state(source)\n        assert before_bad['balance'] == 125\n        self.commit(source, 'T104', reset=True)\n        self.commit(source, 'T105', 7)\n        committed = self.state(source)\n        assert committed['balance'] == 7\n        self.sql(source, 'FLUSH BINARY LOGS;')\n        files = self.sql(source, 'SHOW BINARY LOGS;').stdout.decode().splitlines()\n        files = [row.split('\\t')[0] for row in files]\n        chain = files[files.index(start['file']):files.index(stop['file']) + 1]\n        assert len(chain) == 2\n        correct_stream = self.binlog(source, chain, start['position'], stop['position'])\n        whole_stream = self.binlog(source, chain, start['position'])\n        missing_stream = self.binlog(source, chain[1:], 4, stop['position'])\n        target = self.start('restore', 102, False)\n        baseline_only = self.restore(target, baseline)\n        whole_history = self.restore(target, baseline, whole_stream)\n        missing_log = self.restore(target, baseline, missing_stream)\n        recovered = self.restore(target, baseline, correct_stream)\n        # ROW events carry row images, not the original \"balance + delta\" SQL.\n        # Later account after-images can hide a missing earlier receipt.\n        observed = [baseline_only, whole_history, missing_log, recovered]\n        assert [s['balance'] for s in observed] == [100, 7, 125, 125], json.dumps(observed)\n        assert recovered == before_bad\n        assert [op for op, _ in missing_log['operations']] == ['T102', 'T103']\n        reconciliation_gap = missing_log['balance'] - (100 + sum(delta for _, delta in missing_log['operations']))\n        assert reconciliation_gap == 10\n        self.commit(target, 'TNEW', 3)\n        writable_after_restore = self.state(target)\n        assert writable_after_restore['balance'] == 128\n\n        # Hold one uncommitted update while a second session still sees committed balance 7.\n        hold = subprocess.Popen(self.mysql_args(source), stdin=subprocess.PIPE, stdout=subprocess.PIPE,\n                                stderr=subprocess.PIPE)\n        hold.stdin.write(b\"START TRANSACTION;UPDATE lab.account SET balance=999 WHERE id=1;SELECT 'HOLDING';DO SLEEP(60);COMMIT;\")\n        hold.stdin.close()\n        with selectors.DefaultSelector() as selector:\n            selector.register(hold.stdout, selectors.EVENT_READ)\n            assert selector.select(12), 'The holding transaction never acknowledged its update'\n            assert hold.stdout.readline().strip() == b'HOLDING'\n        assert self.state(source) == committed\n        self.docker('kill', '--signal', 'KILL', source)\n        hold.wait(timeout=20)\n        assert hold.returncode != 0\n        self.docker('start', source)\n        self.wait(source)\n        after_crash = self.state(source)\n        assert after_crash == committed, 'Crash recovery keeps the committed bad transaction too'\n        return {'status': 'passed', 'image': self.image, 'image_digests': digest, 'mysql_version': version,\n                'mysqlbinlog_version': binlog_version,\n                'tools_dockerfile_sha256': hashlib.sha256(tool_file.read_bytes()).hexdigest(),\n                'snapshot_next_event': start, 'exclude_bad_transaction_from': stop, 'required_files': chain,\n                'baseline_only': baseline_only, 'full_replay': whole_history,\n                'missing_first_log': missing_log, 'point_in_time_recovery': recovered,\n                'missing_history_reconciliation_gap': reconciliation_gap,\n                'post_restore_write': writable_after_restore,\n                'process_crash': {'uncommitted_value': 999, 'held_client_exit_code': hold.returncode,\n                                  'committed_state_before': committed, 'state_after_restart': after_crash},\n                'stream_sha256': {label: hashlib.sha256(data).hexdigest() for label, data in\n                                  [('baseline', baseline), ('correct', correct_stream), ('full', whole_stream)]},\n                'scope': 'Real isolated MySQL/InnoDB, logical dump, two binlogs, replay and mysqld SIGKILL. '\n                         'No host power-loss, replication, managed database, production load or external application test.'}\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument('--image', default='mysql:8.4')\n    parser.add_argument('--report', type=Path)\n    args = parser.parse_args()\n    # Require an explicit local Unix Docker endpoint; never use a remote user context.\n    context = subprocess.run(['docker', 'context', 'inspect'], capture_output=True, check=True)\n    endpoint = json.loads(context.stdout)[0]['Endpoints']['docker']['Host']\n    if not endpoint.startswith('unix://') or (os.environ.get('DOCKER_HOST') and not os.environ['DOCKER_HOST'].startswith('unix://')):\n        raise RuntimeError('Use a local Unix Docker engine for this isolated lesson')\n    with tempfile.TemporaryDirectory(prefix='infra-mysql-') as directory:\n        lab = Lab(args.image, Path(directory))\n        try:\n            result = lab.run()\n        finally:\n            lab.cleanup()\n    result.update(source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n                  python=platform.python_version(), system=platform.system())\n    serialized = json.dumps(result, ensure_ascii=False, indent=2) + '\\n'\n    if args.report:\n        args.report.write_text(serialized)\n    print(serialized, end='')\n\n\nif __name__ == '__main__':\n    main()\n", "tcp_framing.py": "\"\"\"Length-prefixed messages and half-close over an actual loopback TCP connection.\n\nPython 3.9+, standard library. No external endpoint or privileged port.\n\"\"\"\nimport json\nimport queue\nimport socket\nimport struct\nimport threading\n\nLIMIT = 4096\n\n\ndef frame(text):\n    body = text.encode(\"utf-8\")\n    if len(body) > LIMIT:\n        raise ValueError(\"frame_too_large\")\n    return struct.pack(\"!I\", len(body)) + body\n\n\nclass Decoder:\n    def __init__(self):\n        self.buffer = bytearray()\n\n    def feed(self, chunk):\n        self.buffer.extend(chunk)\n        messages = []\n        while len(self.buffer) >= 4:\n            size = struct.unpack(\"!I\", self.buffer[:4])[0]\n            if size > LIMIT:\n                raise ValueError(\"frame_too_large\")\n            if len(self.buffer) < 4 + size:\n                break\n            body = bytes(self.buffer[4:4 + size])\n            del self.buffer[:4 + size]\n            messages.append(body.decode(\"utf-8\"))\n        return messages\n\n    def finish(self):\n        if self.buffer:\n            raise ValueError(\"truncated_frame\")\n\n\ndef parser_probes(wire, expected):\n    # Segmentation is controlled here, independent of the TCP implementation.\n    patterns = [[wire], [wire[i:i + 1] for i in range(len(wire))],\n                [wire[:2], wire[2:7], wire[7:]]]\n    for chunks in patterns:\n        parser, actual = Decoder(), []\n        for chunk in chunks:\n            actual.extend(parser.feed(chunk))\n        parser.finish()\n        assert actual == expected\n    outcomes = {}\n    for name, bad in [(\"oversized\", struct.pack(\"!I\", LIMIT + 1)),\n                      (\"truncated_header\", wire[:2]),\n                      (\"truncated_body\", wire[:-1])]:\n        parser = Decoder()\n        try:\n            parser.feed(bad)\n            parser.finish()\n        except ValueError as error:\n            outcomes[name] = str(error)\n        else:\n            raise AssertionError(\"invalid input was accepted: \" + name)\n    assert outcomes == {\"oversized\": \"frame_too_large\",\n                        \"truncated_header\": \"truncated_frame\",\n                        \"truncated_body\": \"truncated_frame\"}\n    return {\"segmentation_patterns_passed\": len(patterns), **outcomes}\n\n\ndef main():\n    expected = [\"云上训练\", \"恢复完成\"]\n    wire = b\"\".join(frame(text) for text in expected)\n    probes = parser_probes(wire, expected)\n    result = queue.Queue()\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as listener:\n        listener.bind((\"127.0.0.1\", 0))\n        listener.listen(1)\n        listener.settimeout(5)\n\n        def serve():\n            try:\n                with listener.accept()[0] as conn:\n                    conn.settimeout(5)\n                    parser, messages, reads = Decoder(), [], []\n                    while True:\n                        chunk = conn.recv(7)  # A limit, not a message boundary.\n                        if not chunk:\n                            parser.finish()\n                            break\n                        reads.append(len(chunk))\n                        messages.extend(parser.feed(chunk))\n                    assert messages == expected\n                    # The peer closed its sending direction, not its receiving one.\n                    conn.sendall(frame(\"已接收2条\"))\n                    conn.shutdown(socket.SHUT_WR)\n                    result.put({\"messages\": messages, \"recv_chunk_bytes\": reads,\n                                \"server_saw_eof_before_reply\": True})\n            except Exception as error:\n                result.put(error)\n\n        worker = threading.Thread(target=serve, daemon=True)\n        worker.start()\n        with socket.create_connection(listener.getsockname(), timeout=5) as client:\n            for text in expected:\n                client.sendall(frame(text))\n            client.shutdown(socket.SHUT_WR)\n            parser, replies = Decoder(), []\n            while True:\n                chunk = client.recv(7)\n                if not chunk:\n                    parser.finish()\n                    break\n                replies.extend(parser.feed(chunk))\n        worker.join(timeout=5)\n        assert not worker.is_alive(), \"server did not terminate\"\n        server = result.get(timeout=1)\n        if isinstance(server, Exception):\n            raise server\n    assert replies == [\"已接收2条\"]\n    assert sum(server[\"recv_chunk_bytes\"]) == len(wire)\n    assert len(server[\"recv_chunk_bytes\"]) > 2\n    print(json.dumps({\"transport\": \"AF_INET / 127.0.0.1 / TCP\",\n                      \"sendall_calls\": 2, \"wire_bytes\": len(wire),\n                      \"payload_bytes\": [len(x.encode(\"utf-8\")) for x in expected],\n                      \"payload_characters\": [len(x) for x in expected],\n                      \"parser_probes\": probes, \"server\": server,\n                      \"reply_after_half_close\": replies,\n                      \"scope\": \"loopback TCP and parser; no epoll, loss injection or business commit\"},\n                     ensure_ascii=False))\n\n\nif __name__ == \"__main__\":\n    main()\n", "socket_backpressure.py": "\"\"\"Actual bounded loopback send/receive backpressure; no packet trace or congestion-control benchmark.\"\"\"\nimport hashlib\nimport json\nimport platform\nimport selectors\nimport socket\nfrom threading import Event, Thread\nimport time\n\n\ndef main():\n    payload = b\"infra-local-byte-stream\\n\" * 32768\n    allow_read = Event()\n    received = {}\n    errors = []\n    with socket.socket() as listener:\n        listener.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 16384)\n        listener.bind((\"127.0.0.1\", 0))\n        listener.listen(1)\n        listener.settimeout(5)\n        def receiver():\n            try:\n                with listener.accept()[0] as connection:\n                    connection.settimeout(8)\n                    received[\"receive_buffer_setting\"] = connection.getsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF)\n                    if not allow_read.wait(5):\n                        raise TimeoutError(\"sender_never_released_reader\")\n                    digest = hashlib.sha256()\n                    total = 0\n                    while True:\n                        block = connection.recv(16384)\n                        if not block:\n                            break\n                        total += len(block)\n                        digest.update(block)\n                    received.update(bytes=total, sha256=digest.hexdigest(), saw_eof=True)\n                    connection.sendall(json.dumps({\"bytes\": total, \"sha256\": digest.hexdigest()}).encode())\n            except BaseException as error:\n                errors.append(type(error).__name__+\": \"+str(error))\n        thread = Thread(target=receiver, daemon=True)\n        thread.start()\n        try:\n            with socket.create_connection(listener.getsockname(), timeout=5) as sender:\n                sender.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 16384)\n                send_buffer = sender.getsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF)\n                sender.setblocking(False)\n                offset, calls, short_writes = 0, 0, 0\n                blocked_before_read = False\n                while offset < len(payload):\n                    part = memoryview(payload)[offset:offset+16384]\n                    try:\n                        count = sender.send(part)\n                    except BlockingIOError:\n                        blocked_before_read = True\n                        break\n                    assert count > 0\n                    calls += 1\n                    short_writes += count < len(part)\n                    offset += count\n                accepted_before_read = offset\n                allow_read.set()  # The application reader begins only after this controlled boundary.\n                deadline = time.monotonic()+8\n                with selectors.DefaultSelector() as selector:\n                    selector.register(sender, selectors.EVENT_WRITE)\n                    while offset < len(payload):\n                        if time.monotonic() >= deadline:\n                            raise TimeoutError(\"bounded_transfer_deadline\")\n                        if not selector.select(.1):\n                            continue\n                        part = memoryview(payload)[offset:offset+16384]\n                        try:\n                            count = sender.send(part)\n                        except BlockingIOError:\n                            continue\n                        assert count > 0\n                        calls += 1\n                        short_writes += count < len(part)\n                        offset += count\n                sender.setblocking(True)\n                sender.settimeout(8)\n                sender.shutdown(socket.SHUT_WR)\n                reply = bytearray()\n                while True:\n                    block = sender.recv(1024)\n                    if not block:\n                        break\n                    reply.extend(block)\n                    if len(reply) > 1024:\n                        raise ValueError(\"unexpected_fixture_reply\")\n                receipt = json.loads(reply)\n        finally:\n            allow_read.set()\n            thread.join(10)\n        assert not thread.is_alive() and not errors, errors\n    expected = hashlib.sha256(payload).hexdigest()\n    assert offset == received[\"bytes\"] == receipt[\"bytes\"] == len(payload)\n    assert expected == received[\"sha256\"] == receipt[\"sha256\"]\n    assert received[\"saw_eof\"]\n    print(json.dumps({\"python\": platform.python_version(), \"system\": platform.system(),\n                      \"payload_bytes\": len(payload), \"send_buffer_setting\": send_buffer,\n                      \"receive_buffer_setting\": received[\"receive_buffer_setting\"],\n                      \"blocked_before_application_read\": blocked_before_read,\n                      \"accepted_before_application_read\": accepted_before_read,\n                      \"successful_send_calls\": calls, \"short_writes_observed\": short_writes,\n                      \"received_bytes\": receipt[\"bytes\"], \"sha256\": expected,\n                      \"read_reply_after_write_shutdown\": True,\n                      \"scope\": \"actual_loopback_nonblocking_send_and_application_drain_not_packet_or_cwnd_measurement\",\n                      \"limits\": [\"send accepted bytes into a local socket path, not proof that receiver application read them\",\n                                 \"paused application may still have bytes received/acknowledged by its kernel\",\n                                 \"buffer settings and partial-write boundaries depend on the OS; cap does not force a block on every stack\",\n                                 \"receiver JSON is this fixture's explicit application receipt, not TCP ACK\"]}, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "Dockerfile.tools": "# Server-minimal images omit mysqlbinlog. Keep the full client in a separate image.\nARG MYSQL_BASE=mysql:8.4\nFROM ${MYSQL_BASE} AS vendor_key\nFROM oraclelinux:9-slim\nCOPY --from=vendor_key /etc/pki/rpm-gpg/RPM-GPG-KEY-mysql /etc/pki/rpm-gpg/RPM-GPG-KEY-mysql\nRUN printf '%s\\n' \\\n    '[mysql84-client]' \\\n    'name=MySQL 8.4 Community client tools' \\\n    'baseurl=https://repo.mysql.com/yum/mysql-8.4-community/el/9/$basearch/' \\\n    'enabled=1' \\\n    'gpgcheck=1' \\\n    'gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-mysql' \\\n    'module_hotfixes=true' > /etc/yum.repos.d/mysql84-client.repo \\\n    && microdnf install -y mysql-community-client \\\n    && microdnf clean all \\\n    && mysqlbinlog --version\nENTRYPOINT [\"mysqlbinlog\"]\n", "README.md": "# TCP、原生epoll与MySQL恢复\n\n四个程序分别验证字节消息、发送背压、Linux通知和真实数据库恢复。它们不是同一个生产系统。源码不需要第三方Python包。\n\n## 从可预测结果开始\n\n|程序|环境|先预测什么|\n|---|---|---|\n|tcp_framing.py|Python3.9+，本地TCP|两条16字节帧；EOF后仍可收回应；残帧要拒绝|\n|socket_backpressure.py|Python3.9+，本地TCP|总共768KiB，排空后摘要相同；阻塞与短写边界依系统而变|\n|epoll_ready.py|Linux与Python3.9+|写abcdef、先读ab；无新写入时LT再通知，ET不保证重复通知；应用队列继续cd、ef到EAGAIN|\n|mysql_restore.py|本地Unix Docker引擎；可下载官方镜像|基线100、完整重放7；两种125只有一份业务历史完整；新写后128|\n\n```sh\npython3 tcp_framing.py\npython3 socket_backpressure.py\npython3 epoll_ready.py\npython3 mysql_restore.py --report mysql-local.json\n```\n\nMySQL脚本与Dockerfile.tools必须在同一目录。它创建随机前缀的两套容器与数据卷，不暴露端口、不连接已有数据库；结束时仅清理自己创建的容器、卷与工具镜像。运行期间约需两套小型数据库的内存与磁盘空间，首次下载及构建所需时间另计。容器与Dockerfile只使用官方MySQL/Oracle Linux镜像与MySQL官方签名软件包。\n\n精简MySQL服务器镜像不一定包含mysqlbinlog。Dockerfile.tools安装完整客户端，读取实验日志时以无网络、只读日志卷方式运行。报告给出实际服务器版本、镜像摘要与客户端版本；重跑时可用`--image mysql@sha256:...`指定报告中的服务器镜像摘要。工具软件包可能更新，应继续核对实际版本与配方摘要。\n\n## 为什么两个125不能一起判为成功\n\n源业务从100开始：T101加10、T102加20、T103减5，余额125；T104误清零，T105再加7，余额7。每笔余额变化和业务回执在同一InnoDB事务提交。\n\n- 只恢复基线：余额100，没有后续回执。\n- 重放全部历史：余额7，误操作也被恢复。\n- 漏掉第一个日志，只重放第二个到清零前：ROW事件仍可把账户写到125，但只有T102、T103回执。账本校验为125−(100+20−5)=10，拒绝放行。\n- 连续重放到清零前：余额125，T101、T102、T103完整，差额0。\n- 正确目标再写TNEW加3：余额128，原回执保留。\n\n行事件记录列映像，不等于重新执行原加法SQL；不同表结构、主键和日志配置的缺段结果可以不同。这个反例只证明余额单项不能认证完整历史。\n\n进程崩溃对照另外保持一笔未提交的999，强制结束并重启源mysqld：当前已提交余额7仍在，999不成为已提交结果。崩溃恢复保持提交事实，PITR另选历史目标。本例未执行宿主机断电、主从复制、托管数据库或真实应用切流。\n\n## 运行证据\n\nvalidation.json分别记录本机TCP与Linux CI结果，附源码摘要和CI提交/运行链接。macOS运行epoll程序会如实报告unsupported，不把它改成模拟通过。MySQL只有实际Linux容器结果，不声称本机Docker引擎已启动。\n\n网站构建时核对源码、内嵌代码、ZIP与执行摘要。修改程序后应重新执行；普通页面检查不自动启动两套MySQL并冒充旧实验已重跑。\n"};
