const transportTCPSections=[
 ['先认识套接字、连接与字节流',
 para('进程不能直接把一段内存交给另一台机器上的进程。它先通过操作系统提供的套接字接口收发数据。文件描述符（fd）是进程引用一个已打开对象的整数；它不是远端地址，也不是一条消息。普通TCP连接由两端的IP与端口等信息区分，客户端通常使用临时端口，服务端在约定端口监听。',
 '监听套接字负责接纳连接。accept返回另一个套接字，应用通过它处理某个已建立连接；监听端仍可继续接纳其他客户端。因此一个服务只有一个监听端口，也可以同时拥有许多连接和描述符。连接关闭后，描述符整数还可能被系统复用，不能把一个迟到事件里的整数永久当作原连接身份。',
 'TCP向应用提供有序字节流。发送端两次写入，接收端可以分多次读出；一次读取也可能同时包含几次写入的数据。操作系统处理序号、确认与重传，应用负责从连续字节里识别请求、检查权限并完成业务。后面的长度头、接收缓冲与事件循环，都是在这条分工线上展开。')+
 table(['对象','它表示什么','不能直接推出什么'],[
 ['监听套接字','一个接纳连接的入口','某个请求已经被应用处理'],
 ['已连接套接字','一条双向字节通道的本地接口','一次read恰好得到一条消息'],
 ['应用请求','协议定义的完整消息和意图','TCP已经替它完成业务提交']])],
 ['连接建立后，序号怎样对应到字节',
 para('序号给流中的字节定位。下面固定一组教学数值：客户端初始序号1000，服务端初始序号7000。SYN是同步序号的控制标志，ACK表示确认，FIN用于结束一个发送方向。普通握手中，客户端发SYN，服务端用SYN和ACK回应，客户端再确认服务端的初始序号。SYN各占一个序号位置，因此两端首个数据字节分别从1001和7001开始。',
 '第三步让服务端知道，客户端收到了它给出的连接信息与初始序号。握手建立的是当前连接的传输状态，应用还可能需要TLS、身份认证与协议协商。本例只讨论普通打开，省略同时打开、携带数据的握手及其他扩展。')+
 figure('v45-tcp-byte-positions','序号手算，不是抓包记录。客户端发送两份16字节帧，共32字节；服务端的应用回执为17字节。SYN和FIN分别占一个序号位置，纯ACK不占。')+
 para('两条消息各包含4字节长度头和12字节正文，客户端的数据区间就是[1001,1033)。确认号1033表示：在本例的累计确认口径下，下一个期待的字节位置为1033。若[1017,1033)尚未收到，累计确认不能凭后面的数据直接越过缺口。重传的仍是原字节区间，不会把同一份重传当成流中新增的16字节。',
 '这不是“一份报文对应一次请求”的编号。TCP分段方式会受写入、缓冲和网络路径影响，同一个32字节应用输入可以有不同的传输分段。若需要判断实际包序、重传和时延，就必须另取抓包与传输统计；本章的回环程序并未注入丢包或采集这些数据。')],
 ['字节怎样成为两条完整消息',
 para('先定义协议，再写解析器。本例规定：前4字节用大端无符号整数表示正文的字节数，随后是该长度的UTF-8正文。大端表示高位字节在前。长度按编码后的字节计算，不按汉字数量计算。“云上训练”和“恢复完成”都各有4个汉字、12个UTF-8字节，因此每帧16字节，两帧共32字节。')+
 figure('v45-tcp-frame-grid','相同32字节可以整段交付、逐字节交付或按其他长度交付。解析器先收齐4字节头，再收齐声明长度的正文；UTF-8解码发生在完整正文上。')+
 para('接收缓冲保存尚未处理完的字节。少于4字节时等待；够头部但正文不足时继续等待；够一帧时取出正文，保留后续字节，再检查是否还有下一帧。把每个recv块直接decode，可能切断一个汉字的多字节编码；把每个块直接当消息，又会把一个请求拆开或把多个请求混在一起。')+
 code('本例解析循环的核心 · 完整类见实验','PYTHON',
 'while len(buffer) >= 4:\n    size = struct.unpack("!I", buffer[:4])[0]\n    if size > LIMIT:\n        raise ValueError("frame_too_large")\n    if len(buffer) < 4 + size:\n        break\n    body = bytes(buffer[4:4 + size])\n    del buffer[:4 + size]\n    messages.append(body.decode("utf-8"))')+
 para('长度头也是不可信输入。本例最多接受4096字节正文，超限立即拒绝；对端发送结束后，如果还残留半个头或半段正文，就报告截断，而不是把残留字节当成成功请求。在生产协议中还需给连接数、累计缓冲、空闲时间与消息处理量设边界。仅限制单帧长度，不能限制所有连接的总内存。')],
 ['半关闭后，为什么还能收到回应',
 para('TCP的两个发送方向可以分别结束。客户端调用shutdown(SHUT_WR)，表示本端不再发送新数据；已经排队的字节仍按传输流程发送，随后发送方向结束。服务端把之前的数据读完后，recv返回空字节串b\'\'，表达这一方向的有序结束。它与“暂时没有数据可读”是两个结果。',
 '本例服务端在读到这个结束标志后，才发送“已接收2条”。这条回执的正文是13字节，加上4字节长度头，共17字节。客户端虽然结束了写方向，读方向仍然打开，所以能收到回执。这能解释上传后等待处理结果、代理排空和流式请求的部分行为。')+
 table(['观察或状态','含义','应用需要做什么'],[
 ['recv返回b\'\'','该流的对端发送方向已结束，且先前字节已读尽','完成协议截断检查，决定是否发送最后响应和关闭本端'],
 ['CLOSE_WAIT','本端已收到对端的结束，本端尚未完成关闭','检查应用的资源释放与结束路径'],
 ['TIME_WAIT','正常关闭路径中的一端暂时保留连接状态','结合关闭模式、连接复用和端口压力分析；不是未关fd的同义词'],
 ['RST或连接重置错误','连接被中止或相应状态不再接受当前传输','把传输失败与业务是否已生效分别核对']])+
 para('正常双向结束需要双方各自表达结束并得到确认，但确认和结束可以合并在同一报文中，不能用“四次挥手”推断实际一定抓到四个独立包。TIME_WAIT按协议的报文生存时间机制理解，不能把某个平台常见秒数当作全部实现的固定值。更不能看到大量CLOSE_WAIT就先缩短TIME_WAIT：前者首先应查应用为什么没有完成自己的关闭。')],
 ['发送成功、流量控制与应用背压',
 para('send返回正数，说明本次调用接受了这么多字节；它不证明远端应用已经读取，更不证明业务事务已提交。非阻塞发送还可能只接受一部分字节，程序必须保存偏移，在之后继续发送剩余部分。对端读得慢时，本地发送路径最终可能暂时无法继续接受数据。',
 '流量控制关注接收端还有多少接收能力，拥塞控制关注网络路径上应允许多少在途数据。粗略讨论某一时刻的发送限制时，可以同时考虑接收窗口与拥塞窗口；它们的具体更新还取决于实际协议状态。应用层的处理队列又在这两层之外：即使内核还能收字节，数据库或业务线程池也可能已经排满。')+
 knowledgeFormula('只做带宽与往返时间的量纲估算','100 Mbit/s × 0.020 s = 2,000,000 bit = 250,000 B','这是题设下的带宽时延积，约244 KiB；没有计协议开销，不是本章实测吞吐，也不直接给出某个socket应设置的缓冲大小。')+
 para('背压是把下游压力向上游传递：输出缓冲过大时减少继续接受的工作，业务队列已满时限制准入，恢复后再放行。如果只是把所有输入不断放进内存，事件循环依旧能“很快读完”，系统却可能因排队、超时和内存增长而失败。超时后的重试还会制造更多尝试量，容量预算应包含这些重复工作。',
 '配套程序让接收方应用暂缓读取，再排空768 KiB数据，最后返回字节数和摘要。本次本机记录出现了暂时无法发送，未观察到短写；不同系统的缓冲与短写边界可能不同。程序仍按偏移处理每次正数返回，并用最终总字节与摘要验收完整性。这个回执由本例应用生成，不是TCP ACK。')],
 ['非阻塞I/O：就绪、操作与业务完成',
 para('阻塞调用可以让当前线程等待；非阻塞调用在暂时无法推进时返回相应结果。以非阻塞流读取为例：正数表示取得字节，EAGAIN或EWOULDBLOCK表示当前暂时无法取得更多字节，零表示前面介绍的有序结束，其他错误按错误类型处理。Python把“暂时无法推进”通常表现为BlockingIOError。',
 'I/O多路复用让一个线程等待多个描述符的就绪情况。epoll是Linux提供的一种接口：先登记感兴趣的描述符和读写事件，再等待就绪通知。登记集合回答“我想观察谁”，就绪列表回答“哪些对象目前值得尝试处理”。收到可读通知后，应用仍要read、积累缓冲、解析消息，再安排业务；内核没有因此替应用完成SQL或工具调用。')+
 table(['阶段','本章对应动作','失败时最容易混淆的地方'],[
 ['就绪','epoll返回可读、可写或结束相关事件','认为一个通知等于一条完整请求'],
 ['I/O操作','非阻塞读写并更新缓冲、偏移和连接状态','把EAGAIN当作EOF，或漏掉剩余发送字节'],
 ['业务处理','完整消息进入有界队列，执行授权、计算或提交','在事件线程执行长任务，阻塞所有其他连接'],
 ['结果交付','编码响应，排空输出，按协议结束','以本地写入成功代替用户已收到结果']])+
 para('同一个通知里可以同时包含可读和关闭相关标志。应用要按照实际API语义消费已到达的数据并判断结束，不能仅看到关闭标志就丢掉尚未读出的输入。另一个极端是无条件监听可写：普通空闲连接常常一直可写，如果根本没有待发数据，也可能让轮询反复返回。应按输出缓冲的需要开启和撤销写关注。')],
 ['LT与ET：通知规则怎样影响读取循环',
 para('水平触发（LT）可以在就绪条件仍成立时继续通知；边沿触发（ET）不会保证对尚未处理完的同一份输入持续重复通知。把两者放到一根真实Linux管道上看：先写入abcdef共6字节，第一次通知后只读取ab，内核中还剩cdef。没有新写入时，实验中LT再次返回可读，ET的再次等待则没有新事件。',
 '因此“没有新事件”不能反推“缓冲中没有数据”。配合ET的常见处理方式是使用非阻塞描述符，把当前可推进的读写处理到EAGAIN；遇到EOF或错误则进入对应结束路径。若只读取固定两字节就把处理责任完全交回内核，应用可能等在已经存在的数据前面。')+
 figure('v45-epoll-readiness','Linux原生管道实验：同样先读ab、留下cdef。右侧额外展示应用就绪队列，按两字节预算轮转到EAGAIN；没有用模型伪装epoll调用。')+
 para('“读到EAGAIN”还要和公平性一起考虑：一个热连接如果长时间占用事件线程，其他连接会饥饿。可以给每轮设置字节或工作预算，并把尚未完成的描述符保留在应用自己的就绪队列里，下轮继续；只有确认暂时无法推进，才等待下一次内核通知。EOF和错误则结束相应处理。这里的应用队列与epoll的内核就绪列表是两个对象。',
 '实验把每轮读取预算设为2字节，用一次内核通知得到应用序列ab→cd→ef→EAGAIN。最后一次尝试确认了当前数据已排空。另一个socket实验连续轮询三次空输出连接，都得到可写；撤销写关注后不再返回这些空工作。这些是通知与系统调用结果，未测量CPU占用或生产连接容量。')],
 ['先预测，再运行四组观察',
 para('先写下四个预测：32字节输入经过recv(7)，能否按两次send还原成两次read；客户端结束写方向后能否收回应；ET只读ab后再次等待是否得到通知；没有输出时一直关注可写会发生什么。再分别运行程序，核对观察对象。')+
 transportLab('tcp_framing.py','tcp-framing-run')+
 para('核对wire_bytes=32、两条中文消息、三种人为切块方式，以及超长/残缺输入被拒绝。真实recv块长可能变化，不要把某次[7,7,2,…]当作TCP固定切分规则。服务端记录先看到EOF再发回应，客户端仍读到“已接收2条”。')+
 transportLab('socket_backpressure.py','tcp-backpressure-run')+
 para('核对received_bytes=786432及双方摘要相同，再看本次是否出现EAGAIN与短写。缓冲设置值、实际读取块和成功发送次数是平台观察，不作为跨机器性能排名。')+
 transportLab('epoll_ready.py','native-epoll-run')+
 para('本机macOS会明确报告unsupported；原生epoll结果来自Linux CI，附源码摘要和运行链接。可在Linux直接运行该标准库程序，不需要连接外部地址。检查LT/ET的第二次通知、应用队列四轮，以及可写关注的3→0结果。')],
 ['把机制用于诊断与面试表达',
 table(['现象','先核对哪一层','需要补什么证据'],[
 ['连接迟迟不能建立','监听、去回程、访问策略和握手','同一源/目的条件下的连接状态与必要抓包'],
 ['连接还在，但一条请求被拆坏','应用协议与接收缓冲','原始字节、长度定义、截断和多帧输入测试'],
 ['CLOSE_WAIT持续增长','应用结束与资源释放','哪个读路径看到EOF，哪个分支未完成关闭'],
 ['事件循环频繁醒来却没有工作','监听集合与输出队列','返回的事件位、待发字节与关注更新'],
 ['ET连接停住而缓冲仍有数据','未排空输入或应用调度责任丢失','读返回值、EAGAIN与应用就绪队列'],
 ['发送已成功，业务仍超时','传输确认之后的应用执行','原请求ID、权威回执与数据库提交状态']])+
 para('面试回答可沿同一条链展开：套接字引用连接，TCP交付有序字节，应用协议恢复消息，I/O通知安排尝试，有界执行管理业务，应用回执确认结果。然后给出一个能推翻简单结论的反例：没有新ET事件却仍有未读字节，或者工具请求已送达却尚未确认业务提交。')+
 '<p>'+linkTo('network-diagnosis','把连接、首字节和传输时刻放回排查路径')+linkTo('mysql-recovery','继续区分数据库提交、崩溃恢复与历史恢复')+'</p>']
];
