const continuousDepthFiles={"runtime-scheduling": {"README.md": "# 容器资源与Pod放置：两项真实Linux实验\n\n先读C4.1的对象、视图和资源，再读C4.4的准入与节点过滤。两项实验独立运行。\n\n## 环境\n\n- Python 3.9+标准库、可访问的本地Linux Docker引擎、cgroup v2。\n- 调度实验另需kubectl与kind v0.33.0。安装方法见 https://kind.sigs.k8s.io/docs/user/quick-start/ 。Linux CI按官方sha256文件校验kind二进制。\n- schedule_lab.py固定kindest/node:v1.35.8及内容摘要；需要下载节点镜像和pause:3.10。\n- 客户端只接受本地Unix socket上下文，不接受DOCKER_HOST。macOS的Docker环境仍需提供Linux内核；读数属于该Linux环境。\n- 实验创建有上限的负载和一个三节点kind集群，会占用本地磁盘/内存。使用可清理的学习或CI环境。\n\n## 容器实验\n\n```sh\npython3 -B container_limits.py --output runs/container-record.json\n```\n\n只创建随机命名的自有容器。CPU=0.5、memory=96MiB、pids=16、network=none；复制container_probe.py后实际运行。结束删除自有容器，保留报告。\n\n核对：cpu.max为50000 100000；忙循环的usage及nr_throttled增量为正；主进程+等待线程达到pids上限后再创建被拒绝，max事件增加；OOM对照同时满足退出137和OOMKilled=true。两个同时存活的容器比较PID/mount/network namespace，避免退出后的编号复用。实际计数和耗时随机器变化，不比较固定性能。\n\n## 调度实验\n\n```sh\npython3 -B schedule_lab.py --output runs/scheduling-record.json\n```\n\n创建本次随机命名的kind集群。所有kubectl命令显式指定临时kubeconfig与context，finally只删除该集群。每个节点通过自己的CRI拉取pause镜像，不依赖Docker多平台导出。无需将业务kubeconfig交给实验。\n\n依次核对：300m配额已有250m再加100m被拒绝且无第二对象；单Pod请求超过每个节点CPU时Unschedulable、无绑定；小Pod能运行；反亲和+污点阻止第二Pod，添加容忍后绑定另一节点，第三Pod仍因两个主机域都已占用而等待。\n\n## 已有证据与边界\n\nvalidation.json来自2026-11-08成功的公共Linux CI，包含运行URL、固定源提交、版本、原始条件/事件、对象UID和程序摘要。它不是本机刚运行的报告。\n\nkind的多节点容器共享一台宿主，不能把节点报告的Allocatable相加当物理供给。本实验不验证跨主机网络、云CNI/CSI、生产伸缩、隔离逃逸或性能。源程序只读cgroup文件，不修改宿主cgroup设置。\n", "container_limits.py": "\"\"\"Actual Docker/cgroup-v2 observations. Only UUID-owned containers are removed.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport subprocess\nimport uuid\n\n\ndef run(*args, check=True):\n    return subprocess.run(args, text=True, capture_output=True, check=check, timeout=180)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--output', type=Path, default=Path('container-record.json'))\n    args = ap.parse_args()\n    assert not os.environ.get('DOCKER_HOST'), 'Use a local Docker context, not DOCKER_HOST'\n    endpoint = json.loads(run('docker', 'context', 'inspect').stdout)[0]['Endpoints']['docker']['Host']\n    assert endpoint.startswith('unix://'), 'This lab only accepts a local Unix socket'\n    info = json.loads(run('docker', 'info', '--format', '{{json .}}').stdout)\n    assert str(info['CgroupVersion']) == '2', 'cgroup v2 is required'\n    assert info['OSType'] == 'linux'\n    image = 'python:3.12-alpine'\n    run('docker', 'pull', image)\n    image_info = json.loads(run('docker', 'image', 'inspect', image).stdout)[0]\n    # Resolve once, then use the same immutable content for all cases.\n    digest = image_info['RepoDigests'][0]\n    source = Path(__file__).with_name('container_probe.py')\n    owned = []\n    rows = []\n    try:\n        for mode in ('cpu', 'pids', 'oom'):\n            name = 'infra-limits-' + uuid.uuid4().hex[:12]\n            owned.append(name)\n            run('docker', 'create', '--name', name, '--network', 'none', '--cpus', '.5',\n                '--memory', '96m', '--memory-swap', '96m', '--pids-limit', '16',\n                digest, 'python', '/probe.py', mode)\n            run('docker', 'cp', str(source), name + ':/probe.py')\n            result = run('docker', 'start', '-a', name, check=False)\n            inspection = json.loads(run('docker', 'inspect', name).stdout)[0]\n            state = inspection['State']\n            if mode == 'oom':\n                row = {'mode': mode, 'exit_code': state['ExitCode'], 'oom_killed': state['OOMKilled']}\n                assert row['exit_code'] == 137 and row['oom_killed'], row\n            else:\n                assert result.returncode == 0, result.stderr\n                row = json.loads(result.stdout)\n                assert row['pid'] == 1 and row['memory_max'] == 96 * 1024**2\n                assert row['cpu_max'] == '50000 100000' and row['pids_max'] == 16\n                if mode == 'cpu':\n                    assert row['cpu_stat_delta']['nr_throttled'] > 0, row\n                    assert row['cpu_stat_delta']['usage_usec'] > 0\n                else:\n                    assert row['refusal'] and row['pids_current'] <= 16\n                    assert 0 < row['created_threads'] < 32 and row['pids_max_events_delta'] > 0\n            rows.append(row)\n        # Compare concurrent lifetimes: namespace inode numbers can be reused after exit.\n        live_namespaces = []\n        for _ in range(2):\n            name = 'infra-limits-' + uuid.uuid4().hex[:12]\n            owned.append(name)\n            run('docker', 'run', '-d', '--name', name, '--network', 'none', '--memory', '96m',\n                '--pids-limit', '16', digest, 'python', '-c', 'import time; time.sleep(300)')\n            script = 'import json,os; print(json.dumps({n:os.readlink(\"/proc/1/ns/\"+n) for n in (\"pid\",\"mnt\",\"net\")}))'\n            live_namespaces.append(json.loads(run('docker', 'exec', name, 'python', '-c', script).stdout))\n        for ns in ('pid', 'mnt', 'net'):\n            assert live_namespaces[0][ns] != live_namespaces[1][ns]\n        report = {'schema': 1, 'scope': 'real Linux Docker, cgroup v2; not a sandbox escape test',\n                  'host': platform.platform(), 'docker_server': info['ServerVersion'],\n                  'image': digest, 'cases': rows, 'concurrent_namespaces': live_namespaces,\n                  'source_sha256': {p.name: hashlib.sha256(p.read_bytes()).hexdigest()\n                                    for p in (Path(__file__), source)}}\n        args.output.parent.mkdir(parents=True, exist_ok=True)\n        args.output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\\n')\n        print(json.dumps(report, ensure_ascii=False))\n    finally:\n        for name in owned:\n            run('docker', 'rm', '-f', name, check=False)\n\n\nif __name__ == '__main__':\n    main()\n", "container_probe.py": "\"\"\"Run inside an owned Linux container; never writes host cgroup settings.\"\"\"\nimport json\nimport os\nfrom pathlib import Path\nimport sys\nimport threading\nimport time\n\nCG = Path('/sys/fs/cgroup')\n\n\ndef counters(name):\n    return {k: int(v) for k, v in (line.split() for line in (CG / name).read_text().splitlines())}\n\n\nmode = sys.argv[1]\nif mode == 'oom':\n    # Touch all pages: an address reservation alone does not exercise the limit.\n    blocks = []\n    for _ in range(256):\n        blocks.append(bytearray(b'x' * (1024 * 1024)))\n    raise AssertionError('Expected the 96 MiB cgroup limit to stop this process')\n\nrow = {'mode': mode, 'pid': os.getpid(),\n       'namespaces': {n: os.readlink('/proc/self/ns/' + n) for n in ('pid', 'mnt', 'net')},\n       'cpu_max': (CG / 'cpu.max').read_text().strip(),\n       'memory_max': int((CG / 'memory.max').read_text()),\n       'pids_max': int((CG / 'pids.max').read_text())}\nif mode == 'cpu':\n    before = counters('cpu.stat')\n    start = time.monotonic()\n    x = 1\n    while time.monotonic() - start < 2.5:\n        x = (x * 17 + 3) % 1000003\n    after = counters('cpu.stat')\n    row.update(wall_seconds=time.monotonic() - start,\n               cpu_stat_delta={k: after[k] - before[k] for k in before}, checksum=x)\nelif mode == 'pids':\n    before = counters('pids.events')\n    stop = threading.Event()\n    threads = []\n    error = None\n    try:\n        for _ in range(32):\n            t = threading.Thread(target=stop.wait)\n            try:\n                t.start()\n                threads.append(t)\n            except RuntimeError as exc:\n                error = str(exc)\n                break\n        row.update(created_threads=len(threads), refusal=error,\n                   pids_current=int((CG / 'pids.current').read_text()),\n                   pids_max_events_delta=counters('pids.events')['max'] - before['max'])\n    finally:\n        stop.set()\n        for t in threads:\n            t.join()\nelse:\n    raise ValueError(mode)\nprint(json.dumps(row, sort_keys=True))\n", "schedule_lab.py": "\"\"\"Create an isolated kind cluster. Every API call names its own kubeconfig/context.\"\"\"\nimport argparse\nfrom decimal import Decimal\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport tempfile\nimport time\nimport uuid\n\nNODE_IMAGE = 'kindest/node:v1.35.8@sha256:07b2536e30b803ed61d1677a79df6115f798ce64c80f9e22f6ed45afd09323c0'\nPAUSE = 'registry.k8s.io/pause:3.10'\n\n\ndef command(*args, data=None, check=True, timeout=240):\n    result = subprocess.run(args, input=data, text=True, capture_output=True, timeout=timeout)\n    if check and result.returncode:\n        raise RuntimeError(f'{args[0]} failed: {result.stderr[-6000:]}')\n    return result\n\n\ndef milli(value):\n    return int(value[:-1]) if value.endswith('m') else int(Decimal(value) * 1000)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--output', type=Path, default=Path('scheduling-record.json'))\n    args = ap.parse_args()\n    assert not os.environ.get('DOCKER_HOST'), 'Use a local Docker context'\n    context = json.loads(command('docker', 'context', 'inspect').stdout)[0]\n    assert context['Endpoints']['docker']['Host'].startswith('unix://')\n    name = 'infra-schedule-' + uuid.uuid4().hex[:10]\n    assert name not in command('kind', 'get', 'clusters').stdout.splitlines()\n    observations = {}\n    with tempfile.TemporaryDirectory(prefix='infra-kind-') as tmp:\n        kubeconfig = Path(tmp) / 'kubeconfig'\n        config = Path(tmp) / 'kind.yaml'\n        config.write_text('kind: Cluster\\napiVersion: kind.x-k8s.io/v1alpha4\\nnodes:\\n'\n                          '- role: control-plane\\n- role: worker\\n- role: worker\\n')\n\n        def kubectl(*parts, data=None, check=True):\n            return command('kubectl', '--kubeconfig', str(kubeconfig), '--context', 'kind-' + name,\n                           '--request-timeout=30s', *parts, data=data, check=check)\n\n        def apply(obj, check=True):\n            return kubectl('apply', '-f', '-', data=json.dumps(obj), check=check)\n\n        def get(kind, obj=None, namespace=None):\n            parts = ['get', kind] + ([obj] if obj else []) + (['-n', namespace] if namespace else [])\n            return json.loads(kubectl(*parts, '-o', 'json').stdout)\n\n        def wait_pod(namespace, pod, ready):\n            deadline = time.monotonic() + 100\n            while time.monotonic() < deadline:\n                obj = get('pod', pod, namespace)\n                conds = obj.get('status', {}).get('conditions', [])\n                if ready:\n                    ok = any(c['type'] == 'Ready' and c['status'] == 'True' for c in conds)\n                else:\n                    ok = any(c['type'] == 'PodScheduled' and c['status'] == 'False'\n                             and c.get('reason') == 'Unschedulable' for c in conds)\n                if ok:\n                    return {'uid': obj['metadata']['uid'], 'phase': obj['status']['phase'],\n                            'node': obj['spec'].get('nodeName'), 'conditions': conds}\n                time.sleep(.5)\n            raise AssertionError(f'{namespace}/{pod}: unexpected status {obj.get(\"status\")}')\n\n        def pod(namespace, podname, cpu='50m', spread=False, tolerate=False):\n            spec = {'nodeSelector': {'guide/pool': 'worker'},\n                    'containers': [{'name': 'idle', 'image': PAUSE, 'imagePullPolicy': 'Never',\n                                    'resources': {'requests': {'cpu': cpu, 'memory': '16Mi'},\n                                                  'limits': {'cpu': cpu, 'memory': '32Mi'}}}]}\n            if spread:\n                spec['affinity'] = {'podAntiAffinity': {'requiredDuringSchedulingIgnoredDuringExecution': [\n                    {'labelSelector': {'matchLabels': {'app': 'spread'}}, 'topologyKey': 'kubernetes.io/hostname'}]}}\n            if tolerate:\n                spec['tolerations'] = [{'key': 'dedicated', 'operator': 'Equal', 'value': 'training', 'effect': 'NoSchedule'}]\n            return {'apiVersion': 'v1', 'kind': 'Pod', 'metadata': {'namespace': namespace,\n                    'name': podname, 'labels': {'app': 'spread' if spread else 'idle'}}, 'spec': spec}\n\n        try:\n            command('kind', 'create', 'cluster', '--name', name, '--kubeconfig', str(kubeconfig),\n                    '--config', str(config), '--image', NODE_IMAGE, '--wait', '150s', timeout=400)\n            # Pull through each node's CRI, avoiding Docker multi-platform export differences.\n            for node in command('kind', 'get', 'nodes', '--name', name).stdout.splitlines():\n                command('docker', 'exec', node, 'crictl', 'pull', PAUSE)\n            nodes = get('nodes')['items']\n            workers = sorted(n['metadata']['name'] for n in nodes if 'node-role.kubernetes.io/control-plane' not in n['metadata']['labels'])\n            assert len(workers) == 2\n            for node in workers:\n                kubectl('label', 'node', node, 'guide/pool=worker')\n            kubectl('taint', 'node', workers[1], 'dedicated=training:NoSchedule')\n            for ns in ('quota-lab', 'shape-lab', 'spread-lab'):\n                apply({'apiVersion': 'v1', 'kind': 'Namespace', 'metadata': {'name': ns}})\n            apply({'apiVersion': 'v1', 'kind': 'ResourceQuota', 'metadata': {'name': 'cpu-budget', 'namespace': 'quota-lab'},\n                   'spec': {'hard': {'requests.cpu': '300m'}}})\n            apply(pod('quota-lab', 'first', cpu='250m'))\n            observations['quota_first'] = wait_pod('quota-lab', 'first', True)\n            rejected = apply(pod('quota-lab', 'second', cpu='100m'), check=False)\n            assert rejected.returncode != 0 and 'exceeded quota' in rejected.stderr, rejected.stderr\n            absent = kubectl('get', 'pod', 'second', '-n', 'quota-lab', '--ignore-not-found', '-o', 'name').stdout.strip()\n            assert absent == ''\n            observations['quota_rejection'] = {'object_exists': False, 'error': rejected.stderr.strip(),\n                                               'quota': get('resourcequota', 'cpu-budget', 'quota-lab')['status']}\n            allocatable = {n['metadata']['name']: n['status']['allocatable'] for n in get('nodes')['items'] if n['metadata']['name'] in workers}\n            oversized = max(milli(v['cpu']) for v in allocatable.values()) + 1000\n            apply(pod('shape-lab', 'too-large', cpu=str(oversized) + 'm', tolerate=True))\n            observations['oversized'] = wait_pod('shape-lab', 'too-large', False)\n            observations['oversized']['request_millicpu'] = oversized\n            apply(pod('shape-lab', 'fits', tolerate=True))\n            observations['fits'] = wait_pod('shape-lab', 'fits', True)\n            apply(pod('spread-lab', 'spread-0', spread=True))\n            observations['spread_first'] = wait_pod('spread-lab', 'spread-0', True)\n            assert observations['spread_first']['node'] == workers[0]\n            apply(pod('spread-lab', 'spread-1', spread=True))\n            observations['spread_blocked'] = wait_pod('spread-lab', 'spread-1', False)\n            kubectl('patch', 'pod', 'spread-1', '-n', 'spread-lab', '--type=merge', '-p', json.dumps({\n                'spec': {'tolerations': [{'key': 'dedicated', 'operator': 'Equal', 'value': 'training', 'effect': 'NoSchedule'}]}}))\n            observations['spread_tolerated'] = wait_pod('spread-lab', 'spread-1', True)\n            assert observations['spread_tolerated']['node'] == workers[1]\n            apply(pod('spread-lab', 'spread-2', spread=True, tolerate=True))\n            observations['spread_full'] = wait_pod('spread-lab', 'spread-2', False)\n            events = get('events', namespace='spread-lab')['items']\n            report = {'schema': 1, 'scope': 'actual kind API/scheduler on one Linux host; logical nodes, not physical multi-node capacity',\n                      'kind': command('kind', 'version').stdout.strip(), 'node_image': NODE_IMAGE,\n                      'kubernetes': json.loads(kubectl('version', '-o', 'json').stdout)['serverVersion'],\n                      'allocatable': allocatable, 'workers': workers, 'observations': observations,\n                      'events': [{'reason': e.get('reason'), 'message': e.get('message'),\n                                  'object': e['involvedObject']['name']} for e in events],\n                      'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}\n            args.output.parent.mkdir(parents=True, exist_ok=True)\n            args.output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\\n')\n            print(json.dumps(report, ensure_ascii=False))\n        finally:\n            command('kind', 'delete', 'cluster', '--name', name, check=False)\n\n\nif __name__ == '__main__':\n    main()\n"}, "speculative-decoding": {"README.md": "# 推测解码：先验证分布，再验证真实缓存\n\n## 1. 无依赖的精确概率程序\n\n```sh\npython3 -B exact_sampling.py\n```\n\nPython 3.9+标准库。用Fraction精确计算三词元分布p=[1/2,1/3,1/6]、q=[1/6,1/3,1/2]；接受质量2/3，拒绝后残差[1,0,0]。错误地用p作为拒绝后分布得到[1/3,4/9,2/9]。\n\n进一步枚举前缀相关的k=2草稿与多轮输出，逐项核对长度3的27条序列等于普通目标采样概率。也核对p=q与q中含零的边界。这是有限系统中的精确分布，不是蒙特卡洛频率或实际语言质量。\n\n## 2. 实际CPU注意力与K/V张量\n\n使用Python 3.10–3.12（与PyTorch 2.5.1轮子匹配），示例：\n\n```sh\npython3.12 -m venv .venv\n.venv/bin/pip install torch==2.5.1\n.venv/bin/python -B cache_verify.py\n```\n\nCPU即可。实际记录使用PyTorch 2.5.1、float64、词表8、隐藏宽度8、单层因果注意力、固定权重种子19。前缀[1,2,3]，草稿[0,4,3]全接受，最终输出[0,4,3,0]、缓存7行；改为[0,5,3]后第二个拒绝，裁缓存6→4，消费修正4后5行。与完整前缀和逐词目标对照，误差阈值1e-12。\n\n不裁剪的负例得到7行缓存，下一步分数最大误差约0.450285。调用数按共同预填充后、输出已全部消费进缓存的边界统计，不能当加速倍数。\n\n草稿是根据目标预生成并故意改错的可控夹具，模型未经训练，不衡量独立草稿模型接受率。随机分布证明与贪心缓存验证是不同层证据；没有GPU内核、墙钟加速、真实分词器或生产服务测量。\n\nvalidation.json保存本轮既有执行结果与源码摘要；重新运行会得到本机结果，不会自动改写已有记录。\n", "cache_verify.py": "\"\"\"Actual tiny CPU attention + KV tensors. Drafts are controlled fixtures, not a trained model.\"\"\"\nimport json\nimport math\nimport torch\n\ntorch.set_num_threads(1)\nDTYPE = torch.float64\n\n\nclass TinyAttention:\n    def __init__(self):\n        g = torch.Generator().manual_seed(19)\n        self.emb = torch.randn(8, 8, generator=g, dtype=DTYPE)\n        self.pos = torch.randn(32, 8, generator=g, dtype=DTYPE) * .1\n        self.weights = [torch.randn(8, 8, generator=g, dtype=DTYPE) / math.sqrt(8) for _ in range(5)]\n\n    def forward(self, tokens, past=None):\n        n = 0 if past is None else past[0].shape[0]\n        x = self.emb[torch.tensor(tokens)] + self.pos[n:n + len(tokens)]\n        wq, wk, wv, wo, wl = self.weights\n        q, k, v = x @ wq, x @ wk, x @ wv\n        if past is not None:\n            k, v = torch.cat((past[0], k)), torch.cat((past[1], v))\n        scores = q @ k.T / math.sqrt(8)\n        mask = torch.arange(k.shape[0])[None, :] > (n + torch.arange(len(tokens)))[:, None]\n        scores = scores.masked_fill(mask, float('-inf'))\n        hidden = x + torch.softmax(scores, dim=-1) @ v @ wo\n        return hidden @ wl, (k, v)\n\n\ndef max_error(a, b):\n    return (a - b).abs().max().item()\n\n\ndef run_case(model, prefix, draft, initial_logits, initial_cache):\n    verifier_logits, speculative_cache = model.forward(draft, initial_cache)\n    p_logits = [initial_logits[-1]] + list(verifier_logits)\n    # Independent serial/full-prefix execution for every conditional distribution.\n    conditional_errors = []\n    for i in range(len(draft) + 1):\n        reference, _ = model.forward(prefix + draft[:i])\n        error = max_error(p_logits[i], reference[-1])\n        assert error < 1e-12\n        conditional_errors.append(error)\n    accepted = 0\n    for i, y in enumerate(draft):\n        if y != int(p_logits[i].argmax()):\n            break\n        accepted += 1\n    correction_or_bonus = int(p_logits[accepted].argmax())\n    output = draft[:accepted] + [correction_or_bonus]\n    # Keep only committed prefix K/V. Rejected guesses must not survive the cut.\n    keep = len(prefix) + accepted\n    trimmed = tuple(x[:keep].clone() for x in speculative_cache)\n    next_logits, committed_cache = model.forward([correction_or_bonus], trimmed)\n    serial_cache = initial_cache\n    serial_logits = initial_logits\n    serial_output = []\n    for _ in output:\n        token = int(serial_logits[-1].argmax())\n        serial_output.append(token)\n        serial_logits, serial_cache = model.forward([token], serial_cache)\n    assert output == serial_output\n    errors = [max_error(a, b) for a, b in zip(committed_cache, serial_cache)]\n    assert max(errors + [max_error(next_logits, serial_logits)]) < 1e-12\n    negative = None\n    if accepted < len(draft):\n        wrong_logits, wrong_cache = model.forward([correction_or_bonus], speculative_cache)\n        negative = {'wrong_cache_length': wrong_cache[0].shape[0],\n                    'correct_cache_length': committed_cache[0].shape[0],\n                    'next_logit_max_error': max_error(wrong_logits, serial_logits)}\n        assert negative['wrong_cache_length'] != negative['correct_cache_length']\n        assert negative['next_logit_max_error'] > 1e-5\n    return {'prefix': prefix, 'draft_fixture': draft, 'accepted': accepted, 'output': output,\n            'serial_target_output': serial_output, 'conditional_max_errors': conditional_errors,\n            'verified_cache_length': speculative_cache[0].shape[0], 'retained_before_correction': keep,\n            'committed_cache_length': committed_cache[0].shape[0], 'cache_max_errors': errors,\n            'next_logit_max_error': max_error(next_logits, serial_logits),\n            'target_calls_after_prefill': {'verify': 1, 'consume_correction_or_bonus': 1,\n                                           'serial_consuming_same_output': len(output)},\n            'negative_keep_rejected_cache': negative}\n\n\ndef main():\n    model = TinyAttention()\n    prefix = [1, 2, 3]\n    initial_logits, initial_cache = model.forward(prefix)\n    logits, cache = initial_logits, initial_cache\n    target_fixture = []\n    for _ in range(3):\n        token = int(logits[-1].argmax())\n        target_fixture.append(token)\n        logits, cache = model.forward([token], cache)\n    good = run_case(model, prefix, target_fixture, initial_logits, initial_cache)\n    assert good['accepted'] == 3 and len(good['output']) == 4\n    bad = target_fixture.copy()\n    bad[1] = (bad[1] + 1) % 8\n    rejected = run_case(model, prefix, bad, initial_logits, initial_cache)\n    assert rejected['accepted'] == 1 and len(rejected['output']) == 2\n    print(json.dumps({'torch': torch.__version__, 'device': 'cpu', 'dtype': str(DTYPE),\n                      'vocabulary': 8, 'hidden_width': 8, 'all_accept': good, 'reject_second': rejected,\n                      'scope': 'actual untrained one-layer CPU causal attention/KV verification; '\n                               'controlled drafts, no trained draft quality or GPU speedup measurement'}, indent=2))\n\n\nif __name__ == '__main__':\n    with torch.inference_mode():\n        main()\n", "exact_sampling.py": "\"\"\"Exact finite-state probability enumeration, not Monte Carlo or a speed test.\"\"\"\nfrom collections import defaultdict\nfrom fractions import Fraction as F\nfrom itertools import product\nimport json\n\nP = (F(1, 2), F(1, 3), F(1, 6))\nQ = (F(1, 6), F(1, 3), F(1, 2))\n\n\ndef normalize(values):\n    total = sum(values)\n    assert total > 0\n    return tuple(v / total for v in values)\n\n\ndef one_step(p, q, wrong_residual=False):\n    accepted = tuple(min(a, b) for a, b in zip(p, q))\n    rejected = 1 - sum(accepted)\n    if not rejected:\n        return accepted\n    residual = p if wrong_residual else normalize(tuple(max(F(0), a - b) for a, b in zip(p, q)))\n    return tuple(a + rejected * r for a, r in zip(accepted, residual))\n\n\ndef distribution(base, prefix):\n    # Prefix-dependent transition: rotate the table by the last output token.\n    offset = prefix[-1] if prefix else 0\n    return tuple(base[(i + offset) % 3] for i in range(3))\n\n\ndef block(prefix, gamma=2):\n    outcomes = defaultdict(F)\n    for draft in product(range(3), repeat=gamma):\n        draft_mass = F(1)\n        for i, y in enumerate(draft):\n            draft_mass *= distribution(Q, prefix + draft[:i])[y]\n        live_mass = draft_mass\n        for i, y in enumerate(draft):\n            accepted_prefix = prefix + draft[:i]\n            p = distribution(P, accepted_prefix)\n            q = distribution(Q, accepted_prefix)\n            accept = min(F(1), p[y] / q[y])\n            rejection_mass = live_mass * (1 - accept)\n            if rejection_mass:\n                residual = normalize(tuple(max(F(0), a - b) for a, b in zip(p, q)))\n                for token, mass in enumerate(residual):\n                    outcomes[draft[:i] + (token,)] += rejection_mass * mass\n            live_mass *= accept\n        # Every guess survived: one additional token from p at the full prefix.\n        for token, mass in enumerate(distribution(P, prefix + draft)):\n            outcomes[draft + (token,)] += live_mass * mass\n    assert sum(outcomes.values()) == 1\n    return {k: v for k, v in outcomes.items() if v}\n\n\ndef full_sequences(length):\n    result = defaultdict(F)\n\n    def visit(prefix, mass):\n        if len(prefix) >= length:\n            result[prefix[:length]] += mass\n            return\n        for tokens, probability in block(prefix).items():\n            visit(prefix + tokens, mass * probability)\n    visit((), F(1))\n    return result\n\n\ndef main():\n    correct = one_step(P, Q)\n    wrong = one_step(P, Q, wrong_residual=True)\n    assert correct == P and wrong != P\n    assert one_step(P, P) == P  # no rejection: never divide by zero residual mass\n    zero_q = (F(0), F(1, 2), F(1, 2))\n    assert one_step(P, zero_q) == P  # q=0 cannot propose; residual restores missing support\n    actual = full_sequences(3)\n    expected = {}\n    for seq in product(range(3), repeat=3):\n        mass = F(1)\n        for i, token in enumerate(seq):\n            mass *= distribution(P, seq[:i])[token]\n        expected[seq] = mass\n    assert dict(actual) == expected and sum(actual.values()) == 1\n    report = {'p': list(map(str, P)), 'q': list(map(str, Q)),\n              'accepted_mass': list(map(str, map(min, P, Q))), 'acceptance': '2/3',\n              'residual': ['1', '0', '0'], 'correct_marginal': list(map(str, correct)),\n              'wrong_using_p_as_residual': list(map(str, wrong)),\n              'equal_distributions': list(map(str, one_step(P, P))),\n              'zero_draft_support': list(map(str, one_step(P, zero_q))),\n              'gamma': 2, 'sequence_length': 3,\n              'sequence_probabilities': [{'tokens': list(seq), 'mass': str(actual[seq]),\n                                          'target_mass': str(expected[seq])} for seq in sorted(actual)],\n              'scope': 'exact Fraction enumeration of sampling law; no model performance claim'}\n    print(json.dumps(report, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n"}, "agent-crash-windows": {"README.md": "# 六个进程崩溃窗口：意图、回执与恢复\n\nPython 3.9+标准库，POSIX系统（Linux/macOS），无需外部服务：\n\n```sh\nmkdir -p runs\npython3 -B crash_windows.py > runs/crash-record.json\n```\n\n固定业务：为demo增加37，操作身份logical-add-1，最终只允许一个效果。运行器是独立子进程，工具服务是父进程中的本机HTTP服务，监听127.0.0.1随机端口。runner.sqlite/tool.sqlite分离，工具在一个事务内提交账户变化与唯一回执。临时目录只包含本实验数据。\n\n屏障确认六个位置后，以SIGKILL杀死自有运行器：意图后、工具提交前、工具提交后、收到响应后、本地观察后、完成后。工具继续存活，再启动全新运行器恢复。每例分别读本地状态与工具数据库，核对一个效果、总额37、回执内容一致；再次恢复无HTTP调用。\n\n关键中间结果：提交前窗口，运行器已死亡，GET暂时查不到回执，但释放工具屏障后旧请求仍提交。查不到不是“不会再生效”。恢复沿用原身份；工具的同键协议覆盖旧请求迟到。\n\n两个明确负例：恢复换新身份会产生两次效果/74，独立验收拒绝；篡改本地观察37→99也被拒绝。程序总体passed表示负例已被正确识别，不表示负例业务正确。\n\n本轮用Python 3.12.13实际执行；Linux回归也重跑真实子进程。此处验证进程崩溃，不验证物理断电、磁盘缓存、网络分区、多运行器竞争或真实Kairo接入。synchronous=FULL是一项配置，不是断电验收结论。代码没有通用认证服务，固定本地协议的授权边界应继续读G2。\n", "crash_windows.py": "\"\"\"POSIX SIGKILL recovery windows with a surviving HTTP receiver and separate SQLite files.\"\"\"\nimport argparse\nimport hashlib\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nimport json\nimport os\nfrom pathlib import Path\nimport signal\nimport sqlite3\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport urllib.request\nimport uuid\n\nPARAMS = {'account': 'demo', 'amount': 37}\nFINGERPRINT = hashlib.sha256(json.dumps(PARAMS, sort_keys=True, separators=(',', ':')).encode()).hexdigest()\n\n\ndef db(path):\n    conn = sqlite3.connect(path, timeout=10)\n    conn.execute('PRAGMA synchronous=FULL')\n    return conn\n\n\ndef request(base, path, body=None):\n    data = None if body is None else json.dumps(body).encode()\n    req = urllib.request.Request(base + path, data=data, headers={'Content-Type': 'application/json'})\n    with urllib.request.urlopen(req, timeout=15) as response:\n        return json.load(response)\n\n\ndef barrier(name, selected):\n    if name == selected:\n        print(json.dumps({'barrier': name}), flush=True)\n        sys.stdin.readline()  # parent kills this process; no graceful cleanup is assumed\n\n\ndef worker(root, base, selected, recovery=False, new_key=False):\n    path = root / 'runner.sqlite'\n    with db(path) as con:\n        con.execute('CREATE TABLE IF NOT EXISTS task(id INTEGER PRIMARY KEY, op TEXT, fingerprint TEXT, phase TEXT, observation TEXT)')\n        con.execute('INSERT OR IGNORE INTO task VALUES(1,?,?,?,NULL)', ('logical-add-1', FINGERPRINT, 'INTENT'))\n        if new_key:\n            # Explicit negative: a retry has been given a fresh business identity.\n            con.execute('UPDATE task SET op=?, phase=?, observation=NULL WHERE id=1', ('new-' + uuid.uuid4().hex, 'INTENT'))\n    barrier('intent', selected)\n    with db(path) as con:\n        op, fingerprint, phase, observation = con.execute('SELECT op,fingerprint,phase,observation FROM task WHERE id=1').fetchone()\n    assert fingerprint == FINGERPRINT\n    if phase == 'DONE':\n        print(json.dumps({'phase': phase, 'path': 'already_done'}), flush=True)\n        return\n    if phase == 'OBSERVED':\n        receipt = json.loads(observation)\n        path_taken = 'durable_observation'\n    else:\n        receipt = request(base, '/receipt/' + op)['receipt'] if recovery else None\n        path_taken = 'queried_receipt' if receipt else 'submitted_original_operation'\n        if receipt is None:\n            receipt = request(base, '/effect', {'op': op, 'fingerprint': fingerprint, 'params': PARAMS})['receipt']\n        barrier('response', selected)\n        with db(path) as con:\n            con.execute('UPDATE task SET phase=?, observation=? WHERE id=1', ('OBSERVED', json.dumps(receipt)))\n    barrier('observation', selected)\n    assert receipt['op'] == op and receipt['fingerprint'] == fingerprint and receipt['amount'] == 37\n    with db(path) as con:\n        con.execute('UPDATE task SET phase=? WHERE id=1', ('DONE',))\n    barrier('done', selected)\n    print(json.dumps({'phase': 'DONE', 'path': path_taken}), flush=True)\n\n\nclass Receiver(ThreadingHTTPServer):\n    daemon_threads = True\n\n    def __init__(self, path, pause):\n        self.path, self.pause = path, pause\n        self.arrived = threading.Event()\n        self.committed = threading.Event()\n        self.release = threading.Event()\n        self.audit = []\n        with db(path) as con:\n            con.execute('CREATE TABLE counter(value INTEGER NOT NULL)')\n            con.execute('INSERT INTO counter VALUES(0)')\n            con.execute('CREATE TABLE receipt(op TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, amount INTEGER NOT NULL)')\n        super().__init__(('127.0.0.1', 0), Handler)\n\n\nclass Handler(BaseHTTPRequestHandler):\n    def log_message(self, *args):\n        pass\n\n    def reply(self, body):\n        data = json.dumps(body).encode()\n        try:\n            self.send_response(200)\n            self.send_header('Content-Type', 'application/json')\n            self.send_header('Content-Length', str(len(data)))\n            self.end_headers()\n            self.wfile.write(data)\n        except (BrokenPipeError, ConnectionResetError):\n            pass  # killed caller does not roll back receiver commit\n\n    def do_GET(self):\n        op = self.path.removeprefix('/receipt/')\n        with db(self.server.path) as con:\n            row = con.execute('SELECT op,fingerprint,amount FROM receipt WHERE op=?', (op,)).fetchone()\n        self.server.audit.append('receipt_found' if row else 'receipt_absent')\n        self.reply({'receipt': None if row is None else dict(zip(('op', 'fingerprint', 'amount'), row))})\n\n    def do_POST(self):\n        body = json.loads(self.rfile.read(int(self.headers['Content-Length'])))\n        assert self.path == '/effect' and body['params'] == PARAMS and body['fingerprint'] == FINGERPRINT\n        self.server.arrived.set()\n        if self.server.pause == 'before_commit':\n            assert self.server.release.wait(15)\n        with db(self.server.path) as con:\n            con.execute('BEGIN IMMEDIATE')\n            row = con.execute('SELECT op,fingerprint,amount FROM receipt WHERE op=?', (body['op'],)).fetchone()\n            if row:\n                assert row[1] == body['fingerprint']\n                self.server.audit.append('duplicate')\n            else:\n                con.execute('UPDATE counter SET value=value+?', (37,))\n                row = (body['op'], body['fingerprint'], 37)\n                con.execute('INSERT INTO receipt VALUES(?,?,?)', row)\n                self.server.audit.append('effect_commit')\n        self.server.committed.set()\n        if self.server.pause == 'after_commit':\n            assert self.server.release.wait(15)\n        self.reply({'receipt': dict(zip(('op', 'fingerprint', 'amount'), row))})\n\n\ndef facts(root):\n    with db(root / 'runner.sqlite') as con:\n        row = con.execute('SELECT op,phase,observation FROM task WHERE id=1').fetchone()\n    with db(root / 'tool.sqlite') as con:\n        amount = con.execute('SELECT value FROM counter').fetchone()[0]\n        receipts = con.execute('SELECT op,fingerprint,amount FROM receipt ORDER BY op').fetchall()\n    return {'operation': row[0], 'runner_phase': row[1], 'observation': None if row[2] is None else json.loads(row[2]),\n            'amount': amount, 'effects': len(receipts),\n            'receipts': [dict(zip(('op', 'fingerprint', 'amount'), r)) for r in receipts]}\n\n\ndef oracle(state):\n    # Independent receiver truth and business target; a DONE flag alone is insufficient.\n    return (state['runner_phase'] == 'DONE' and state['effects'] == 1 and state['amount'] == 37\n            and state['observation'] == state['receipts'][0]\n            and state['receipts'][0]['op'] == 'logical-add-1')\n\n\ndef run_case(name, negative=False):\n    pause = name if name in ('before_commit', 'after_commit') else ''\n    selected = '' if pause else name\n    with tempfile.TemporaryDirectory(prefix='infra-crash-') as tmp:\n        root = Path(tmp)\n        server = Receiver(root / 'tool.sqlite', pause)\n        thread = threading.Thread(target=server.serve_forever, daemon=True)\n        thread.start()\n        base = 'http://127.0.0.1:' + str(server.server_address[1])\n        cmd = [sys.executable, '-B', str(Path(__file__).resolve()), '--worker', str(root), '--base', base]\n        proc = subprocess.Popen(cmd + ['--barrier', selected], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)\n        try:\n            if pause:\n                event = server.arrived if pause == 'before_commit' else server.committed\n                assert event.wait(10), name\n            else:\n                assert json.loads(proc.stdout.readline()) == {'barrier': selected}\n            proc.kill()\n            proc.wait(timeout=5)\n            assert proc.returncode == -signal.SIGKILL\n            at_crash = facts(root)\n            absent_while_old_request_lives = None\n            if pause == 'before_commit':\n                absent_while_old_request_lives = request(base, '/receipt/logical-add-1')['receipt'] is None\n                assert absent_while_old_request_lives\n            server.release.set()\n            if pause:\n                assert server.committed.wait(10)\n            after_old_request = facts(root)\n            resumed = subprocess.run(cmd + ['--recover'] + (['--new-key'] if negative else []), text=True, capture_output=True, timeout=15)\n            assert resumed.returncode == 0, resumed.stderr\n            recovered = facts(root)\n            accepted = oracle(recovered)\n            assert accepted != negative\n            audit_before_done_retry = len(server.audit)\n            again = subprocess.run(cmd + ['--recover'], text=True, capture_output=True, timeout=15)\n            assert again.returncode == 0, again.stderr\n            assert len(server.audit) == audit_before_done_retry, 'DONE retry must make no receiver calls'\n            corrupted_rejected = None\n            if name == 'observation' and not negative:\n                with db(root / 'runner.sqlite') as con:\n                    observation = recovered['observation'].copy()\n                    observation['amount'] = 99\n                    con.execute('UPDATE task SET observation=? WHERE id=1', (json.dumps(observation),))\n                corrupted_rejected = not oracle(facts(root))\n                assert corrupted_rejected\n            return {'window': name, 'negative_new_identity': negative, 'kill_exit_code': proc.returncode,\n                    'at_crash': at_crash, 'receipt_absent_while_old_request_lives': absent_while_old_request_lives,\n                    'after_old_request': after_old_request, 'recovered': recovered,\n                    'resume_path': json.loads(resumed.stdout)['path'], 'independent_oracle_accepted': accepted,\n                    'done_retry_http_calls': len(server.audit) - audit_before_done_retry,\n                    'corrupt_local_observation_rejected': corrupted_rejected, 'receiver_audit': server.audit}\n        finally:\n            if proc.poll() is None:\n                proc.kill()\n                proc.wait(timeout=5)\n            server.release.set()\n            server.shutdown()\n            server.server_close()\n            thread.join(timeout=2)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--worker', type=Path)\n    ap.add_argument('--base')\n    ap.add_argument('--barrier', default='')\n    ap.add_argument('--recover', action='store_true')\n    ap.add_argument('--new-key', action='store_true')\n    args = ap.parse_args()\n    if args.worker:\n        worker(args.worker, args.base, args.barrier, args.recover, args.new_key)\n        return\n    assert os.name == 'posix', 'This experiment uses POSIX SIGKILL'\n    cases = [run_case(name) for name in ('intent', 'before_commit', 'after_commit', 'response', 'observation', 'done')]\n    negative = run_case('after_commit', negative=True)\n    print(json.dumps({'schema': 1, 'status': 'passed', 'params': PARAMS, 'fingerprint': FINGERPRINT,\n                      'python': sys.version.split()[0], 'sqlite': sqlite3.sqlite_version,\n                      'cases': cases, 'negative': negative,\n                      'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n                      'scope': 'real POSIX process kill and surviving local HTTP receiver, separate SQLite domains; '\n                               'not power-loss durability, network partition, concurrent runners, or Kairo integration'}, indent=2))\n\n\nif __name__ == '__main__':\n    main()\n"}};
