const recoveryDepth=articles.find(a=>a.id==='agent-recovery'),oldRecoverySections=recoveryDepth.sections.slice();
recoveryDepth.sections=[
 ['先画清任务、执行记录与工具端事实',
 para('任务是用户想完成的目标，步骤是其中一个逻辑动作，尝试是执行这个动作的一次具体调用。运行器是安排步骤、调用工具并保存进度的程序；工具服务才真正读取或修改目标资源。本章用一项固定动作贯穿：给demo账户增加37，最终只应增加一次，并留下能核对的回执。',
 '运行器把进度放进runner.sqlite，工具把账户与回执放进tool.sqlite。两者是独立持久化域：一个域内的事务能让相关修改一起提交或回滚，却不会自动控制另一个服务的事务。持久化是把状态提交到能够在所声明故障后重新读取的存储，不是把“做过了”写进聊天摘要。',
 '因此至少有三种事实：运行器曾计划什么，工具实际提交什么，运行器最终确认了什么。它们可以短时不一致。HTTP连接消失、进程退出或本地仍显示执行中，都不能直接替代工具端的提交事实。模型也无法从缺少响应的文字中猜出正确答案。')+
 figure('v48-agent-two-domains','运行器与工具各自提交。工具进程在运行器被杀死后仍存活，响应丢失不会撤回已提交效果；恢复必须重新连接两个域的事实。')+
 table(['记录','保存位置','作用'],[['持久意图','运行器数据库','原动作身份、参数与目标'],['效果及回执','工具数据库同一事务','实际提交的资源变化及结果'],['本地观察','运行器数据库','已经核对并接收的工具结果'],['任务完成','运行器数据库','步骤满足目标后的进度，不代替外部验收']])],
 ['先保存操作身份，再允许外部写入',
 para('操作身份是同一个逻辑副作用的稳定编号，本例为logical-add-1。参数指纹是对规范化参数计算的摘要，帮助接收方发现“同一编号却换了内容”。尝试可以增加，操作身份必须保持不变；只有用户要求的一项新业务动作才应有新身份。',
 '本例先把操作身份、参数指纹与INTENT状态提交到本地数据库，再发请求。INTENT表示动作已准备，不能仅凭它区分“尚未发出”“正在工具端执行”和“已提交但响应丢失”。调用进入不确定窗口后，应按未知结果恢复核对，而不是一律标记失败后重新生成动作。',
 '若先发送写入、后保存身份，运行器可能在效果成功后退出，却没有任何稳定线索认回旧动作。即使工具支持幂等，也无法知道下次新编号与旧编号属于同一笔意图。数据库事务应保持短小：提交意图后再做网络请求，不能靠长期持有本地锁期待把远端纳入事务。')+
 code('关键顺序；完整协议与崩溃点见下方源码','TEXT','本地事务：保存 operation + fingerprint + INTENT → 提交\n网络：向工具提交同一个 operation\n本地事务：保存经核对的回执 + OBSERVED → 提交\n本地事务：满足步骤条件后写 DONE → 提交')+
 para('参数规范化必须明确字段、类型和语义。本章固定account=demo、amount=37，并用排序后的JSON计算指纹。实际API还要规定整数范围、缺省值、币种、资源版本和身份授权；哈希相同只能关联内容，不能证明调用者有权执行。')],
 ['接收方怎样让多次尝试只留下一个效果',
 para('幂等协议规定重复请求如何处理。本章工具以operation为唯一键，在同一事务中检查回执、增加账户、写回执。已有同键同指纹时返回原回执；同键不同指纹必须拒绝，不能把新意图悄悄当作旧结果。效果与回执要共同提交，否则仍可能出现“已经改账却没有去重记录”或“有回执却没有效果”。')+
 code('接收方事务的核心；请求验证与错误路径见完整程序','SQL','BEGIN IMMEDIATE;\nSELECT fingerprint, amount FROM receipt WHERE op = ?;\n-- 不存在时才执行，以下两条属于同一个事务\nUPDATE counter SET value = value + 37;\nINSERT INTO receipt(op, fingerprint, amount) VALUES (?, ?, 37);\nCOMMIT;')+
 para('唯一约束与事务共同处理并发重复，而不是先在进程内字典里查一次。重复请求可以来自超时重试、旧请求迟到或执行者恢复；本章用一个SQLite写事务串行化工具端修改，保证范围限定为这份本地接收协议。任意远端服务若不支持稳定身份与原子回执，运行器不能凭自己的去重表保证外部效果只发生一次。',
 '回执也有生命周期。若接收方删除旧回执，而延迟的重试仍可能到达，旧动作可能再次生效；保留期限应覆盖业务允许的重试与迟到范围，并定义过期身份如何处理。工具自身权限变化、查询权限与写权限分别判断，不能为了查旧回执自动获得新写入授权。')+
 linkTo('agent-security','核对工具提交前授权与回执读取权限')],
 ['从未知到完成，状态要跟着证据推进',
 para('本例只有INTENT、OBSERVED和DONE三个持久状态。它没有把每一个网络瞬间都写成状态：INTENT覆盖多个尚未确认窗口，恢复时查工具回执来区分；OBSERVED表示本地已提交回执；DONE表示运行器已推进任务完成。少量状态也能正确，但每个状态能证明什么必须明确。')+
 figure('v48-agent-crash-window-matrix','六个真实SIGKILL位置覆盖发送前、工具提交前/后、响应后、本地观察后和完成后。表中效果数来自独立工具数据库，不由运行器状态猜测。')+
 para('INTENT恢复先按原操作身份查回执：查到并核对内容后保存观察；查不到时，只能依据接收方同键幂等语义安全重试，或者保持未知并继续对账。OBSERVED恢复可从已持久化、经过核对的回执推进；DONE重复恢复不需要重新调用工具。',
 '“本地已观察”也不是永远可信的魔法字段。应检查回执身份、参数、来源和业务约束；任务最终验收还要与工具端事实或独立产物对照。本实验另外把本地回执的37篡改成99，独立验收立即拒绝，说明不能只看DONE或程序是否退出0。')],
 ['取消和恢复都要尊重已经提交的效果',
 para('取消表示用户或策略不希望任务继续推进，不能让已经发生的外部事实自动消失。先定义取消前可以停止哪些未提交工作，再定义提交后怎样查询、停止后续动作或发起补偿。补偿是一项新的业务动作，可能有自己的权限、失败和重试，不能把它称作数据库回滚。')+
 oldRecoverySections[4][1]],
 ['为什么查不到回执，旧请求仍可能生效',
 para('考虑最容易误判的一段时序：运行器已发出请求，工具线程已经接到，但被实验屏障暂停在提交之前。屏障是测试中把执行停在确定位置、等待放行的控制点。此时父进程用强制终止信号SIGKILL结束运行器，再查询工具，回执确实不存在；接着释放工具线程，原请求继续完成，账户增加37并写回执。客户端进程已经消失，没有让接收方自动停止。')+
 figure('v48-agent-absent-race','真实HTTP时序：GET暂时为空发生在旧POST提交之前。横向位置只表达屏障规定的先后，不表示网络耗时比例。')+
 para('这次“未找到”回答的是查询时刻的记录，不是未来不可能提交的保证。因此恢复不能依据一次空查询就换新操作身份重做。沿用原身份可让正在执行的旧请求和恢复请求在接收方汇合；若接收方还提供取消确认、版本条件或明确的最终查询状态，也应按其协议核对。',
 '如果工具既不支持稳定身份，也不能提供权威查询，遇到这类未知结果就没有通用安全重试答案。可以停在待对账、向业务方查证，或使用事先设计的协调协议。把未知强行归入失败，只是把风险藏进下一次调用。')],
 ['六个崩溃窗口，实际分别恢复了什么',
 para('程序把运行器放在真实独立子进程中，工具HTTP服务留在父进程，二者使用分开的SQLite文件。父进程通过明确屏障确认位置后杀死自己创建的运行器，再启动全新子进程恢复；不靠“睡几十毫秒大概撞上窗口”。临时文件由实验独立创建，退出后清理。')+
 table(['SIGKILL位置','杀死时本地状态/工具效果','恢复路径','最终'],[['意图已保存，尚未发出','INTENT / 0','查询后按原身份提交','DONE / 1次 / 37'],['工具已接到，尚未提交','INTENT / 0','旧请求随后提交，查询认回','DONE / 1次 / 37'],['工具已提交，尚未响应','INTENT / 1','查询原回执','DONE / 1次 / 37'],['收到响应，观察尚未提交','INTENT / 1','查询原回执','DONE / 1次 / 37'],['观察已提交，完成尚未提交','OBSERVED / 1','使用持久观察推进','DONE / 1次 / 37'],['完成已提交','DONE / 1','直接返回，无工具请求','DONE / 1次 / 37']])+
 para('六次退出码都是−9，表示POSIX下子进程被SIGKILL终止；它不是工具业务的返回码。每种恢复之后再重复恢复一次，HTTP请求数都没有增加。验收分别读取运行器状态、工具账户与回执，要求效果一次、总额37、回执与本地观察相符，并保留所有中间状态。',
 '本次验证的是进程崩溃，工具服务与机器仍在运行。SQLite的synchronous=FULL配置不等于已经做了断电、磁盘缓存故障或跨主机测试；这些需要不同故障注入与存储证据。程序也没有验证多运行器竞争接管。下一层的租约为执行资格规定有效期，接收方还需拒绝过期执行者；这些在后续工作流章展开。')+
 linkTo('durable-workflows','继续学习租约、接管与过期执行者')],
 ['两个失败对照：身份改了，或只信本地完成',
 para('第一个负例在工具提交37、运行器尚未收到响应时崩溃。恢复代码故意生成新操作身份，于是工具合理地把它当成另一笔业务，又增加37。结果为74、两份回执；新运行器仍然可以写DONE并正常退出，但独立目标要求只做一次，所以验收拒绝。错误在调用协议，不在接收方没有识别两个不同编号。',
 '第二个负例不重复写工具，而是在正确恢复以后，把本地观察改成amount=99。运行器完成标志仍在，工具事实仍是37；独立校验比较回执内容，识别本地记录与外部事实不符。它说明只统计“任务完成率”可能漏掉语义错误，恢复也要核对目标资源和真实产物。')+
 table(['方案','本地能显示完成吗','工具事实','独立验收'],[['稳定身份恢复','能','1次，37','通过'],['恢复生成新身份','能','2次，74','拒绝'],['篡改本地观察','仍可保留DONE','1次，37；观察写99','拒绝']])+
 para('这两个负例在实验中被有意触发并被判错，整体实验因此通过；不能把“负例脚本运行成功”写成“负例业务正确”。记录中单独保留independent_oracle_accepted=false，便于复核实际失败原因。')],
 ['运行完整实验，再回看最小提交间隙',
 para('Python 3.9+标准库即可运行，实际执行使用Python 3.12.13与SQLite。服务仅监听本机回环随机端口，运行器只向这个本地地址请求，实验只杀死自己创建的子进程。工具是固定教学协议，不是Kairo适配器；Kairo接入还需对接真实工具身份、查询、授权与任务验收接口。')+
 depthRun('agent-crash-windows','crash_windows.py','agent-crash-windows-run','mkdir -p runs\npython3 -B crash_windows.py > runs/crash-record.json')+
 '<details class="full-code"><summary>对照原有最小实验 · 两个数据库的提交间隙</summary>'+oldRecoverySections[2][1]+oldRecoverySections[3][1]+'</details>'+
 para('练习时先画两条提交线，再把崩溃移动到每一个位置：当前证据在哪里、旧请求是否可能还活着、能否按原身份重试、何时需要停止等待对账。能逐项回答，才说明理解了恢复协议；只记“加重试、加检查点”无法解释这些窗口。')]
];
